async function rows(table,key){const c=sb();if(!c){localLoad();return Array.isArray(cache[key])?cache[key]:[];}let data,error;if(c){({data,error}=await c.from(table).select('*').order('created_at',{ascending:false}));}if(error){console.error('[Agrageo]',error);localLoad();return Array.isArray(cache[key])?cache[key]:[];}return Array.isArray(data)?data:[];}
async function uid(){const c=sb();if(!c)return null;try{let {data}=await c.auth.getSession();if(data&&data.session)return data.session.user.id;({data}=await c.auth.getUser());return (data&&data.user)?data.user.id:null;}catch(e){console.error('[Agrageo] uid',e);return null;}}
async function insert(table,obj,key){const c=sb();if(!c){obj.id=obj.id||crypto.randomUUID();(local[key]=local[key]||[]).unshift(obj);saveLocal();toast('Salvo localmente (offline).');return obj;}const payload={...obj,owner_id:await uid()};delete payload.id;delete payload.created_at;if(table==='documents'){delete payload.client_name;delete payload.service_name;payload.content={...(payload.content||{})};if(payload.origin_proposal!==undefined){payload.content.origin_proposal=payload.origin_proposal;}if(payload.contract_id)payload.content.contract_id=payload.contract_id;if(payload.editTexts)payload.content.editTexts=payload.editTexts;delete payload.editTexts;delete payload.contract_id;payload.has_os=!!payload.has_os;payload.has_term=!!payload.has_term;}const {data,error}=await c.from(table).insert(payload).select().single();if(error){console.error('[Agrageo] insert',table,error);toast('Erro ao salvar no servidor: '+(error.message||'verifique a conexão e tente novamente.'));throw error;}toast('Salvo no servidor.');return data;}
async function updateRec(table,id,patch,key){const c=sb();if(!c){const arr=(local[key]=Array.isArray(local[key])?local[key]:[]);cache[key]=arr;const i=arr.findIndex(x=>String(x.id)===String(id));if(i>=0)arr[i]={...arr[i],...patch};else{const rec={id,...patch};arr.unshift(rec);if(cache[key]!==arr)cache[key].unshift(rec);}saveLocal();return {...(i>=0?arr[i]:patch),...patch};}if(table==='documents'){patch={...patch};delete patch.client_name;delete patch.service_name;if(patch.origin_proposal!==undefined){patch.content={...(patch.content||{}),origin_proposal:patch.origin_proposal};}if(patch.has_os!==undefined)patch.has_os=!!patch.has_os;if(patch.has_term!==undefined)patch.has_term=!!patch.has_term;}const {data,error}=await c.from(table).update(patch).eq('id',id).select().single();if(error){console.error('[Agrageo] update',table,error);toast('Erro ao atualizar no servidor: '+(error.message||'tente novamente.'));throw error;}return data;}
async function removeRec(table,id,key){const c=sb();if(!c){local[key]=(Array.isArray(local[key])?local[key]:[]).filter(x=>String(x.id)!==String(id));saveLocal();return;}const {error}=await c.from(table).delete().eq('id',id);if(error){console.error('[Agrageo] delete',table,error);toast('Erro ao excluir no servidor: '+(error.message||'tente novamente.'));throw error;}}
async function load(){if(!await auth())return;cache.clients=await rows('clients','clients');cache.services=await rows('services','services');cache.models=await rows('document_models','models');cache.clauses=await rows('clauses','clauses');const rawDocs=await rows('documents','documents');const docs=(Array.isArray(rawDocs)?rawDocs:[]).map(d=>({...d,origin_proposal:d.origin_proposal||(d.content&&d.content.origin_proposal)||'',contract_id:d.contract_id||(d.content&&d.content.contract_id)||'',editTexts:(d.content&&d.content.editTexts)||d.editTexts||[],client_name:(cache.clients.find(c=>String(c.id)===String(d.client_id))||{}).name||d.client_name||'',service_name:(cache.services.find(v=>String(v.id)===String(d.service_id))||{}).name||d.service_name||''}));cache.proposals=docs.filter(x=>x.document_type==='proposal');cache.contracts=docs.filter(x=>x.document_type==='contract');cache.orders=docs.filter(x=>x.document_type==='work_order');cache.terms=docs.filter(x=>x.document_type==='delivery_term');const rawPay=await rows('payments','payments');cache.payments=Array.isArray(rawPay)?rawPay:(Array.isArray(local.payments)?local.payments:[]);const rawReq=await rows('requests','requests');cache.requests=Array.isArray(rawReq)?rawReq:(Array.isArray(local.requests)?local.requests:[]);const rawProc=await rows('processes','processes');cache.processes=Array.isArray(rawProc)?rawProc:(Array.isArray(local.processes)?local.processes:[]);if(!Array.isArray(cache.clients)||!cache.clients.length)cache.clients=local.clients||[];if(!Array.isArray(cache.services)||!cache.services.length)cache.services=local.services||[];if(!(cache.proposals||[]).length&&!(cache.contracts||[]).length){cache.proposals=local.proposals||[];cache.contracts=local.contracts||[];cache.orders=local.orders||[];cache.terms=local.terms||[];}if(!(cache.requests||[]).length)cache.requests=local.requests||[];const rawFis=await rows('fiscal_obligations','fiscal');cache.fiscal=Array.isArray(rawFis)&&rawFis.length?rawFis:(Array.isArray(local.fiscal)?local.fiscal:[]);if(!(cache.fiscal||[]).length){cache.fiscal=fiscalSeed();local.fiscal=cache.fiscal;saveLocal();}else if(Array.isArray(local.fiscal)){const seen=new Set(local.fiscal.map(x=>String(x.id)));cache.fiscal.forEach(r=>{if(!seen.has(String(r.id)))local.fiscal.unshift(r)});local.fiscal=local.fiscal.filter(x=>cache.fiscal.some(r=>String(r.id)===String(x.id)));saveLocal();}cache.proposals.forEach(d=>{d.client_name=(cache.clients.find(c=>String(c.id)===String(d.client_id))||{}).name||d.client_name||'';});cache.contracts.forEach(d=>{d.client_name=(cache.clients.find(c=>String(c.id)===String(d.client_id))||{}).name||d.client_name||'';});(cache.orders||[]).forEach(d=>{d.client_name=(cache.clients.find(c=>String(c.id)===String(d.client_id))||{}).name||d.client_name||'';});(cache.terms||[]).forEach(d=>{d.client_name=(cache.clients.find(c=>String(c.id)===String(d.client_id))||{}).name||d.client_name||'';});render(view);}
// ── Financeiro helpers (tabela payments; se não existir ainda no banco, degrada para localStorage sem quebrar) ──
const allDocs=()=>[...cache.proposals,...cache.contracts,...(cache.orders||[]),...(cache.terms||[])];
const docById=id=>allDocs().find(d=>String(d.id)===String(id));
