async function savePayment(rec){const c=sb();if(!c){rec.id=rec.id||crypto.randomUUID();local.payments=local.payments||[];const i=local.payments.findIndex(x=>String(x.id)===String(rec.id));if(i>=0)local.payments[i]=rec;else local.payments.unshift(rec);saveLocal();toast('Salvo localmente (offline).');return rec;}const {data,error}=await c.from('payments').upsert(rec,{onConflict:'id'}).select().single();if(error){console.error('[Agrageo] payment',error);throw new Error((error.message||'').includes('payments')?'Tabela payments ainda não existe no Supabase — rode a migração 004_payments.sql no SQL Editor.':error.message);}if(!local.payments)local.payments=[];const i=local.payments.findIndex(x=>String(x.id)===String(data.id));if(i>=0)local.payments[i]=data;else local.payments.unshift(data);saveLocal();return data;}
async function deletePayment(id){const c=sb();if(c){const {error}=await c.from('payments').delete().eq('id',id);if(error)throw error;}local.payments=(local.payments||[]).filter(x=>String(x.id)!==String(id));saveLocal();}
