const REQ_STATUS={novo:'Novo',em_analise:'Em análise',orcamento:'Orçamento enviado',negociando:'Negociando',convertido:'Virou proposta',ganhou:'Ganho',perdido:'Perdido'};
function nextReqNumber(){const y=new Date().getFullYear(),arr=cache.requests||[],maxNum=arr.reduce((m,x)=>{const mm=String(x.number||'').match(/(\d+)\s*$/);return Math.max(m,mm?Number(mm[1]):0);},0);return 'REQ-'+y+'-'+String(maxNum+1).padStart(4,'0');}
async function saveRequest(rec){const c=sb();if(!c){rec.id=rec.id||crypto.randomUUID();local.requests=local.requests||[];const i=local.requests.findIndex(x=>String(x.id)===String(rec.id));if(i>=0)local.requests[i]=rec;else local.requests.unshift(rec);saveLocal();toast('Salvo localmente (offline).');return rec;}const payload={...rec};delete payload.created_at;if(payload.owner_id===undefined)payload.owner_id=await uid();const {data,error}=await c.from('requests').upsert(payload,{onConflict:'id'}).select().single();if(error){console.error('[Agrageo] request',error);toast('Erro ao salvar solicitação: '+(error.message||'verifique a conexão.'));throw error;}local.requests=local.requests||[];const i2=local.requests.findIndex(x=>String(x.id)===String(data.id));if(i2>=0)local.requests[i2]=data;else local.requests.unshift(data);saveLocal();return data;}
function reqForm(existing){const rec=existing||null;const clOpts=cache.clients.map(x=>`<option value="${esc(x.id)}"${rec&&String(rec.client_id)===x.id?' selected':''}>${esc(x.name)}</option>`).join('');const stOpts=Object.entries(REQ_STATUS).map(([v,l])=>`<option value="${v}"${(rec?.status||'novo')===v?' selected':''}>${l}</option>`).join('');const areas=(rec&&Array.isArray(rec.areas))?rec.areas:[{}];modalBox(rec?'Editar solicitação':'Nova solicitação de cliente',`<form id="req-form"><div class="form-grid"><div class="field full"><label>Título / escopo resumido *</label><input class="input" name="title" required placeholder="Ex.: Georreferenciamento e laudo de verificação — matrículas 914/949/952/4143" value="${esc(rec?.title)}"></div><div class="field"><label>Cliente</label><select class="select" name="client_id"><option value="">Selecione</option>${clOpts}</select></div><div class="field"><label>Nome do solicitante</label><input class="input" name="client_name" placeholder="Quem pediu (mesmo sem cadastro)" value="${esc(rec?.client_name)}"></div><div class="field"><label>Telefone / WhatsApp</label><input class="input" name="phone" value="${esc(rec?.phone)}"></div><div class="field"><label>E-mail</label><input class="input" name="email" type="email" value="${esc(rec?.email)}"></div><div class="field"><label>Origem</label><select class="select" name="source">${['WhatsApp','E-mail','Indicação','Site','Ligação','Presencial'].map(s=>`<option${(rec?.source||'WhatsApp')===s?' selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Status</label><select class="select" name="status">${stOpts}</select></div><div class="field"><label>Local do imóvel / município</label><input class="input" name="location" placeholder="Ex.: Nova Ubiratã/MT" value="${esc(rec?.location)}"></div><div class="field"><label>Prazo desejado</label><input class="input" name="deadline" placeholder="Ex.: entregar orçamento em 3 dias" value="${esc(rec?.deadline)}"></div><div class="field full"><label>Descrição da demanda (cole o texto recebido)</label><textarea class="textarea" style="min-height:140px" name="description" placeholder="Cole aqui a mensagem do cliente com o escopo completo.">${esc(rec?.description)}</textarea></div><div class="field full"><label>Áreas / matrículas <span class="muted" style="font-weight:400">(uma por linha — formato livre)</span></label><textarea class="textarea" name="areas_raw" placeholder="Matrícula 914 (CRI Vera/MT): 3.678,40 ha&#10;Fazenda Missioneira I, II e III: 2.998,8972 ha">${esc((Array.isArray(rec?.areas)?rec.areas:[]).map(a=>a.line||a).join('\n'))}</textarea></div><div class="field full"><label>O que o cliente solicita</label><textarea class="textarea" name="requested_items" placeholder="Ex.: orçamento e prazo de execução; comprovação de especialidade para emissão de ART.">${esc(rec?.requested_items)}</textarea></div></div></form>`,async()=>{const f=document.getElementById('req-form');const d=Object.fromEntries(new FormData(f));const areas=d.areas_raw.split(/\n+/).map(s=>s.trim()).filter(Boolean).map(line=>({line}));const payload={status:d.status||'novo',title:d.title,client_id:d.client_id||null,client_name:d.client_name||(cache.clients.find(x=>String(x.id)===String(d.client_id))||{}).name||'',email:d.email,phone:d.phone,source:d.source,location:d.location,deadline:d.deadline,description:d.description,areas,requested_items:d.requested_items,number:rec?.number||nextReqNumber()};try{const saved=await saveRequest({...payload,id:rec?.id});const i=(cache.requests||[]).findIndex(x=>String(x.id)===String(saved.id));if(i>=0)cache.requests[i]={...cache.requests[i],...payload,...saved};else{(cache.requests=cache.requests||[]).unshift({...payload,...saved});}modal.innerHTML='';toast('Solicitação salva.');render(view);bind();}catch(e){}});}
function reqWaContact(r){const ph=String(r.phone||'').replace(/\D/g,'');let msg='Olá'+(r.client_name?', '+String(r.client_name).split(' ')[0]:'')+'! Aqui é da Agrageo Consultoria, sobre a solicitação "'+String(r.title||'').slice(0,80)+'". Recebemos sua demanda e em breve enviamos o orçamento com prazo de execução. Qualquer informação adicional que agilize (matrículas, documentos do imóvel), pode nos enviar por aqui. — Agrageo Consultoria'.replace(/\s+/g,' ').trim();window.open('https://wa.me/'+ph+(ph?'?text='+encodeURIComponent(msg):''),'_blank');if(!ph)toast('Sem telefone na solicitação — cadastre para abrir o WhatsApp.');}
function reqToProposal(r){const pool=cache.proposals.filter(p=>p.status==='draft');const opts=pool.map(p=>`<option value="${esc(p.id)}">${esc(p.number)} — ${esc(p.client_name||'')}</option>`).join('');modalBox('Gerar proposta para esta solicitação',`<p class="muted">Crie antes uma proposta normal em <strong>Propostas → ＋ Nova proposta</strong> (com os serviços e fichas técnicas) e depois vincule aqui — ou selecione uma proposta em rascunho já existente:</p><div class="field"${pool.length?'':' style="display:none"'}><label>Proposta em rascunho</label><select class="select" id="req-prop-sel">${opts}</select></div>${pool.length?'':'<div class="alert-box">Nenhuma proposta em rascunho encontrada. Crie uma primeiro — ela aparecerá aqui.</div>'}<div class="field" style="margin-top:10px"><button class="btn small" id="req-new-prop">＋ Abrir nova proposta agora</button></div>`,async()=>{const sel=document.getElementById('req-prop-sel');if(!sel){toast('Abra a tela Propostas e crie uma proposta primeiro.');return;}const p=cache.proposals.find(x=>String(x.id)===String(sel.value));if(!p)return;try{const saved=await saveRequest({...r,status:'convertido',proposal_id:p.id,converted_at:new Date().toISOString()});const i=cache.requests.findIndex(x=>String(x.id)===String(saved.id));if(i>=0)cache.requests[i]={...cache.requests[i],status:'convertido',proposal_id:p.id};modal.innerHTML='';toast('Solicitação vinculada à proposta '+p.number+'.');openDoc(p);}catch(e){}});const nb=document.getElementById('req-new-prop');if(nb)nb.onclick=()=>{modal.innerHTML='';docForm('proposal');};}
function reqList(){const arr=(cache.requests||[]).slice().sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));const chips=['novo','em_analise','orcamento','negociando','convertido','ganhou','perdido'];const head=`<div class="chips"><button class="fchip on" data-fv="">Todas ${arr.length}</button>${chips.map(k=>{const n=arr.filter(x=>(x.status||'novo')===k).length;return `<button class="fchip" data-fv="${k}">${REQ_STATUS[k]}${n?' '+n:''}</button>`;}).join('')}</div>`;const body=arr.length?`<div class="table-wrap"><table class="table"><thead><tr><th data-sort="">Número</th><th>Solicitação</th><th>Cliente / Local</th><th data-sort="">Status</th><th data-sort="">Recebida</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr data-fv="${esc(x.status||'novo')}"><td><strong>${esc(x.number||'—')}</strong></td><td><strong>${esc(x.title)}</strong>${(Array.isArray(x.areas)&&x.areas.length)?'<br><span class="muted">'+esc(String(x.areas[0].line||x.areas[0]).slice(0,60))+(x.areas.length>1?' … ('+x.areas.length+' áreas)':'')+'</span>':''}${x.proposal_id?'<br><span class="badge converted">→ '+esc((cache.proposals.find(p=>String(p.id)===String(x.proposal_id))||{}).number||'proposta')+'</span>':''}</td><td>${esc(x.client_name||'—')}${x.location?'<br><span class="muted">'+esc(x.location)+'</span>':''}<br>${x.phone?'<a href="https://wa.me/'+String(x.phone).replace(/\D/g,'')+'" target="_blank" class="muted">💬 '+esc(x.phone)+'</a>':''}</td><td><button class="badge ${esc(x.status||'novo')} status-btn" data-reqstatus="${esc(x.id)}" title="Clique para alterar o status">${REQ_STATUS[x.status||'novo']||x.status||'Novo'} ▾</button></td><td>${esc(x.created_at?new Date(x.created_at).toLocaleDateString('pt-BR'):'')}</td><td><button class="btn small" data-reqedit="${esc(x.id)}">✎ Editar</button><button class="btn small primary" data-reqprop="${esc(x.id)}">📄 Gerar proposta</button><button class="btn small" data-reqwa="${esc(x.id)}" title="Responder no WhatsApp">💬</button><button class="btn small danger" data-reqdel="${esc(x.id)}">🗑</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma solicitação registrada ainda. Cole aqui a demanda que chegou pelo WhatsApp/e-mail e gere a proposta em 1 clique. Exemplo: "Preciso de georreferenciamento para a matrícula 914 em Nova Ubiratã/MT, com orçamento e ART".</div>';return shell('Solicitações de clientes','<div class="card">'+head+'<div class="toolbar" style="margin-bottom:10px"><input class="input" data-filter placeholder="Pesquisar solicitação, cliente, matrícula..."></div>'+body+'</div>',`<button class="btn primary" data-new="solicitacao">＋ Nova solicitação</button>`);}
function reqStatusPicker(id){const r=(cache.requests||[]).find(x=>String(x.id)===String(id));if(!r)return;modalBox('Alterar status da solicitação',`<p class="muted">${esc(r.number||'')} — ${esc(r.title)}</p>`+Object.entries(REQ_STATUS).map(([v,l])=>`<button class="btn small${v===(r.status||'novo')?' primary':''}" data-setreq="${id}:${v}" style="margin:3px">${l}</button>`).join(''));}
async function setReqStatus(id,st){const r=(cache.requests||[]).find(x=>String(x.id)===String(id));if(!r)return;try{const saved=await saveRequest({...r,status:st});const i=cache.requests.findIndex(x=>String(x.id)===String(id));if(i>=0)cache.requests[i]={...cache.requests[i],status:st,...(saved&&typeof saved==='object'?saved:{})};toast('Status atualizado.');}catch(e){}}
function finStatusOf(doc){const total=Number(doc.value||0),paid=paidSum(doc.id);if(total<=0)return {k:'na',t:'—'};if(paid>=total-0.01)return {k:'quitado',t:'✔ Quitado'};if(paid>0)return {k:'parcial',t:'Parcial '+Math.round(100*paid/total)+'%'};const overdue=payFor(doc.id).some(p=>!p.paid_at&&p.due_date&&new Date(p.due_date+'T23:59:59')<new Date());if(overdue)return {k:'vencido',t:'⚠ Vencida'};return {k:'pendente',t:'Pendente'}}
function payForm(docId,existing){const doc=docById(docId);if(!doc)return;const rec=existing||null;const pend=Math.max(0,Number(doc.value||0)-paidSum(doc.id));modalBox(rec?'Editar parcela':'Nova parcela — '+ (doc.number||''),`<form id="pay-form"><div class="form-grid"><div class="field"><label>Parcela nº</label><input class="input" name="installment" type="number" min="1" value="${rec?Number(rec.installment||1):((payFor(docId).length||0)+1)}"></div><div class="field"><label>Valor (R$)</label><input class="input" name="amount" type="number" step=".01" min="0.01" required value="${rec?(Number(rec.amount)||''):(pend||Number(doc.value||0))}"></div><div class="field"><label>Vencimento</label><input class="input" name="due_date" type="date" value="${esc(rec?.due_date||'')}"></div><div class="field"><label>Pago em (vazio = em aberto)</label><input class="input" name="paid_at" type="date" value="${esc(rec?.paid_at||'')}"></div><div class="field"><label>Forma</label><select class="select" name="method">${['PIX','Transferência','Dinheiro','Cartão','Boleto','Cheque'].map(m=>`<option${(rec?.method||'PIX')===m?' selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label>Observação</label><input class="input" name="notes" value="${esc(rec?.notes||'')}"></div></div></form>`,async()=>{const f=document.getElementById('pay-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));const payload={document_id:docId,installment:Number(d.installment||1),amount:Number(d.amount||0),due_date:d.due_date||null,paid_at:d.paid_at||null,method:d.method||'PIX',notes:d.notes||''};if(rec)payload.id=rec.id;try{const saved=await savePayment(payload);const i=cache.payments.findIndex(x=>String(x.id)===String(saved.id));if(i>=0)cache.payments[i]={...cache.payments[i],...saved};else cache.payments.push(saved);modal.innerHTML='';toast('Parcela salva.');render(view);}catch(e){toast(e.message||'Erro ao salvar parcela.');}});}
function financeiro(){const bills=allDocs().filter(d=>d.status!=='cancelled'&&d.status!=='expired'&&Number(d.value||0)>0);const totContr=bills.filter(d=>d.document_type==='contract'||d.document_type==='work_order'||d.document_type==='delivery_term').reduce((a,d)=>a+Number(d.value||0),0);const recebido=cache.payments.filter(p=>p.paid_at).reduce((a,p)=>a+Number(p.amount||0),0);const previsto=cache.payments.reduce((a,p)=>a+Number(p.amount||0),0);const emAberto=Math.max(0,previsto-recebido);const vencidas=[...new Set(cache.payments.filter(p=>!p.paid_at&&p.due_date&&new Date(p.due_date+'T23:59:59')<new Date()).map(p=>String(p.document_id)))].length;const kpi=(l,v,f)=>`<div class="card"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div><div class="kpi-foot">${f||''}</div></div>`;const rowsHtml=bills.sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)).map(d=>{const fs=finStatusOf(d),pend=Math.max(0,Number(d.value||0)-paidSum(d.id));return `<tr data-fv="${fs.k}"><td><button class="link-btn" data-open="${esc(d.id)}"><strong>${esc(d.number)}</strong></button><div class="muted">${DOCTYPE[d.document_type]||''} • ${esc(d.client_name||'')}</div></td><td>${money(d.value)}</td><td>${money(paidSum(d.id))}</td><td><strong>${money(pend)}</strong></td><td><span class="badge fin-${fs.k}">${fs.t}</span></td><td style="white-space:nowrap"><button class="btn small primary" data-pay="${esc(d.id)}">＋ Parcela</button>${payFor(d.id).length?`<button class="btn small" data-paylist="${esc(d.id)}">Ver ${payFor(d.id).length}</button>`:''}</td></tr>`}).join('');const chips=[['todos','Todos',bills.length],['pendente','Pendentes',bills.filter(d=>finStatusOf(d).k==='pendente').length],['vencido','⚠ Vencidas',bills.filter(d=>finStatusOf(d).k==='vencido').length],['parcial','Parciais',bills.filter(d=>finStatusOf(d).k==='parcial').length],['quitado','Quitados',bills.filter(d=>finStatusOf(d).k==='quitado').length]].map(([k,t,n])=>`<button class="fchip${k==='todos'?' on':''}" data-fs="${k}">${t} <b>${n}</b></button>`).join('');return shell('Financeiro',`<div class="grid kpis" style="margin-bottom:14px">${kpi('Recebido',money(recebido),'parcelas pagas')}${kpi('Em aberto',money(emAberto),'a receber')}${kpi('Previsto (parcelas)',money(previsto),'somatório lançado')}${kpi('Valor contratado',money(totContr),'contratos + OS + termos')}${kpi('Documentos vencidos',vencidas,'com parcela atrasada')}</div><div class="toolbar"><input class="input search" placeholder="Pesquisar documento ou cliente..." data-filter></div><div class="chips">${chips}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th data-sort="">Documento</th><th data-sort="">Valor</th><th data-sort="">Recebido</th><th data-sort="">Em aberto</th><th data-sort="">Status</th><th></th></tr></thead><tbody>${rowsHtml||'<tr><td colspan="6" class="empty">Nenhum documento com valor cadastrado.</td></tr>'}</tbody></table></div></div><div class="muted" style="margin-top:10px">💡 Lance as parcelas de cada contrato (ex.: 50% na contratação, 50% na entrega). O status fica "⚠ Vencida" automaticamente quando um vencimento passa sem pagamento. Se a tabela payments ainda não existir no banco, rode a migração 004_payments.sql no SQL Editor do Supabase.</div>`,'<button class="btn" data-export="fin">⬇ Exportar CSV</button><button class="btn primary" data-new="financeiro">＋ Lançar recebimento</button>');}
// ── Exportação CSV (Excel/contabilidade) — sem dependências externas ──
function csvCell(v){const s=String(v??'').replace(/[\r\n]+/g,' ');return '"'+s.replace(/"/g,'""')+'"';}
function downloadCsv(name,rowsArr){const sep=';';const csv='\uFEFF'+rowsArr.map(r=>r.map(csvCell).join(sep)).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},400);toast('Arquivo '+name+' baixado.');}
function exportFinCsv(){const bills=allDocs().filter(d=>d.status!=='cancelled'&&Number(d.value||0)>0);const rows=[['Documento','Tipo','Cliente','Valor contratado','Recebido','Em aberto','Status financeiro','Parcelas (nº|valor|vencimento|pago|forma)']];bills.forEach(d=>{const fs=finStatusOf(d),pend=Math.max(0,Number(d.value||0)-paidSum(d.id));const pars=payFor(d.id).map(p=>`${p.installment||''}|${Number(p.amount||0).toFixed(2)}|${p.due_date||''}|${p.paid_at||''}|${p.method||''}`).join(' ; ');rows.push([d.number,DOCTYPE[d.document_type]||'',d.client_name||'',Number(d.value||0).toFixed(2),paidSum(d.id).toFixed(2),pend.toFixed(2),fs.t,pars]);});downloadCsv('agrageo-financeiro-'+new Date().toISOString().slice(0,10)+'.csv',rows);}
function exportDocsCsv(){const rows=[['Número','Tipo','Cliente','Serviço','Valor','Status','Emissão','Envio']];allDocs().forEach(d=>{rows.push([d.number,DOCTYPE[d.document_type]||'',d.client_name||'',d.service_name||'',Number(d.value||0).toFixed(2),statusLabel(docTypeOf(d),d.status),(d.created_at||'').slice(0,10),(d.sent_at||'').slice(0,10)]);});downloadCsv('agrageo-documentos-'+new Date().toISOString().slice(0,10)+'.csv',rows);}
function pickDocForPayment(){const docs=allDocs().filter(d=>Number(d.value||0)>0&&!['cancelled','expired'].includes(d.status)).sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));if(!docs.length){toast('Cadastre primeiro uma proposta/contrato com valor.');return;}modalBox('Lançar recebimento — escolher documento',`<div class="field"><label>Documento</label><select class="select" id="pay-doc">${docs.map(d=>`<option value="${esc(d.id)}">${esc(d.number)} — ${esc(d.client_name||'')} (${DOCTYPE[d.document_type]||''}, ${money(d.value)})</option>`).join('')}</select></div>`,()=>{const sel=document.getElementById('pay-doc');modal.innerHTML='';payForm(sel.value);});}
function payListModal(docId){const doc=docById(docId);if(!doc)return;const list=payFor(docId);modalBox('Parcelas de '+(doc.number||''),`<p class="muted">${esc(doc.client_name||'')} • Valor ${money(doc.value)} • Recebido ${money(paidSum(docId))}</p>${list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Valor</th><th>Venc.</th><th>Pago</th><th>Forma</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${esc(p.installment)}</td><td>${money(p.amount)}</td><td>${p.due_date?new Date(p.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</td><td>${p.paid_at?`✔ ${new Date(p.paid_at+'T12:00:00').toLocaleDateString('pt-BR')}`:'<span class="badge fin-pendente">em aberto</span>'}</td><td>${esc(p.method||'PIX')}</td><td style="white-space:nowrap"><button class="btn small" data-payedit="${esc(p.id)}">✎</button><button class="btn small danger" data-paydel="${esc(p.id)}">🗑</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma parcela lançada.</div>'}<button class="btn primary" style="margin-top:12px" id="pay-add">＋ Nova parcela</button>`,()=>{});const addBtn=document.getElementById('pay-add');if(addBtn)addBtn.onclick=()=>{modal.innerHTML='';payForm(docId);};modal.querySelectorAll('[data-payedit]').forEach(b=>b.onclick=()=>{const p=cache.payments.find(x=>String(x.id)===b.dataset.payedit);if(p){modal.innerHTML='';payForm(docId,p);}});modal.querySelectorAll('[data-paydel]').forEach(b=>b.onclick=async()=>{try{await deletePayment(b.dataset.paydel);cache.payments=cache.payments.filter(x=>String(x.id)!==b.dataset.paydel);modal.innerHTML='';toast('Parcela excluída.');render(view);}catch(e){toast('Erro ao excluir parcela.');}});modal.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>modal.innerHTML='');}
// ── Alertas de validade, pipeline visual e novos documentos do fluxo profissional ──
function validityExpired(p){if(!p||p.document_type!=='proposal'||p.status==='converted')return false;const m=String((p.content&&p.content.validity)||p.validity||'').match(/(\d+)/);const days=m?Number(m[1]):15;const base=new Date(p.sent_at||p.created_at||Date.now());if(isNaN(base.getTime()))return false;base.setDate(base.getDate()+days);return base<new Date();}
function alertsPanel(){const exp=cache.proposals.filter(validityExpired);let html='';if(exp.length)html+=`<div class="alert-box">⚠ <strong>${exp.length} proposta(s) com validade vencida:</strong> ${exp.map(x=>`<button class="link-btn" data-open="${esc(x.id)}">${esc(x.number)} — ${esc(x.client_name||'')}</button>`).join(' · ')}. Reenvie ou renegocie.</div>`;const tasks=cobrancaTasks();if(tasks.length){html+=`<div class="card"><div class="section-head"><div><h2>🔔 A fazer hoje</h2><div class="muted">Cobranças e follow-ups priorizados por urgência</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Tarefa</th><th>Documento</th><th>Cliente</th><th>Valor</th><th>Prazo</th><th>Ações</th></tr></thead><tbody>${tasks.slice(0,12).map(t=>`<tr><td><span class="badge ${t.level==='vencida'?'cancelled':t.level==='hoje'?'sent':'active'}">${t.title}</span></td><td><button class="link-btn" data-open="${esc(t.doc.id)}">${esc(t.doc.number)}</button></td><td>${esc(t.doc.client_name||'')}</td><td>${money(t.amount)}</td><td>${t.dueLabel}</td><td style="white-space:nowrap"><button class="btn small" data-cob="${esc(t.doc.id)}:${t.pay?esc(t.pay.id):'-'}" title="Cobrar no WhatsApp">💬 Cobrar</button><button class="btn small primary" data-pay="${esc(t.pay?payDocKey(t):t.doc.id)}" title="Lançar pagamento">✔ Recebido</button></td></tr>`).join('')}</tbody></table></div></div>`;}{const stale=(cache.processes||[]).filter(x=>!['concluido','arquivado'].includes(x.status)&&(!x.last_checked_at||(Date.now()-new Date(x.last_checked_at).getTime())>7*864e5));if(stale.length)html+=`<div class="alert-box">🏛 <strong>${stale.length} processo(s) público(s) sem consulta há +7 dias</strong> — confira SEMA/INCRA/ANM/cartório e registre a verificação. <button class="btn small" data-view-jump="processos">Abrir Processos</button></div>`;}const fis=fisBellItems();if(fis.length){html+='<div class="card"><div class="section-head"><div><h2>🧾 Fiscal — obrigações da empresa</h2><div class="muted">PGDAS-D, DCTFWeb e demais declarações (lembrete diário no sino 🔔)</div></div><button class="btn small" data-view-jump="fiscal">Abrir Fiscal</button></div><div class="table-wrap"><table class="table"><tbody>'+fis.slice(0,6).map(it=>`<tr><td><span class="badge ${it.level==='late'?'cancelled':'sent'}">${it.level==='late'?'⚠ Vencida':'🔔 Em '+it.s.days+' dia(s)'}</span></td><td><strong>${esc(it.rec.name)}</strong><div class="muted">vence dia ${Number(it.rec.due_day)||5} • ref. ${it.ym.split('-').reverse().join('/')}</div></td><td style="white-space:nowrap"><button class="btn small primary" data-fis-mark="${esc(it.rec.id)}:${it.ym}:pago">✔ Paguei/Entreguei</button><button class="btn small" data-fis-mark="${esc(it.rec.id)}:${it.ym}:sem_movimento" title="Entregar zerada">∅ Sem movimento</button></td></tr>`).join('')+'</tbody></table></div></div>';}return html||'';}
// ── Painel "A fazer hoje": parcelas vencidas/a vencer, propostas aguardando, aceite pendente ──
function cobrancaTasks(){try{if(!Array.isArray(cache.payments))cache.payments=[];const today=new Date();today.setHours(0,0,0,0);const fmt=d=>d.toLocaleDateString('pt-BR');const dayMs=864e5,out=[];const seen={};const add=(doc,title,level,pay,dueDate)=>{if(!doc||seen[doc.id+title])return;seen[doc.id+title]=1;out.push({doc,title,level,pay,dueDate,amount:(pay&&Number(pay.amount))||Number(doc&&doc.value||0),dueLabel:dueDate?fmt(dueDate):'—'});};
// 1. Parcelas vencidas (mais urgente)
cache.payments.filter(p=>!p.paid_at&&p.due_date).forEach(p=>{const d=new Date(p.due_date+'T23:59:59');const doc=docById(p.document_id);if(!doc||['cancelled','expired'].includes(doc.status))return;if(d<today){add(doc,'Parcela '+p.installment+' vencida','vencida',p,d);}});
// 2. Vencem hoje / até 7 dias
cache.payments.filter(p=>!p.paid_at&&p.due_date).forEach(p=>{const d=new Date(p.due_date+'T23:59:59');const diff=Math.ceil((d-today)/dayMs);const doc=docById(p.document_id);if(!doc||['cancelled','expired'].includes(doc.status))return;if(diff>=0&&diff<=7)add(doc,diff===0?'Parcela vence hoje':'Parcela a receber','hoje',p,d);});
// 3. Propostas aguardando cliente há mais de 5 dias (follow-up)
cache.proposals.filter(x=>x.status==='sent').forEach(x=>{const base=new Date(x.sent_at||x.created_at||Date.now());if(isNaN(base.getTime()))return;const days=Math.floor((today-new Date(base.getFullYear(),base.getMonth(),base.getDate()))/dayMs);if(days>=5)add(x,'Follow-up: sem resposta há '+days+'d','hoje',null,base);});
// 4. Contratos ativos sem parcela lançada
cache.contracts.filter(c=>c.status==='active'&&Number(c.value||0)>0&&!payFor(c.id).length).forEach(c=>add(c,'Lançar cobrança do contrato','depois',null,null));
// 5. Termo enviado sem aceite há +7 dias
(cache.terms||[]).filter(t=>t.status==='sent'||t.status==='draft').forEach(t=>{const base=new Date(t.sent_at||t.created_at||Date.now());if(isNaN(base.getTime()))return;const days=Math.floor((today-new Date(base.getFullYear(),base.getMonth(),base.getDate()))/dayMs);if(days>=7)add(t,'Cobrar aceite do termo','hoje',null,base);});
// 6. Proposta aprovada ainda não convertida
cache.proposals.filter(x=>x.status==='approved').forEach(x=>add(x,'Converter proposta aprovada em contrato','hoje',null,null));
const rank={vencida:0,hoje:1,depois:2};return out.sort((a,b)=>(rank[a.level]-rank[b.level])||(new Date(a.dueDate||8.64e15)-new Date(b.dueDate||8.64e15)));}catch(e){console.error('[Agrageo] cobrancaTasks',e);return [];}}
function payDocKey(t){return (t.pay&&String(t.pay.document_id))||String(t.doc&&t.doc.id||'');}
function cobrarWhatsApp(doc,pay){const client=cache.clients.find(x=>String(x.id)===String(doc.client_id))||{};const ph=String(client.phone||'').replace(/\D/g,'');let msg='Olá'+(client.name?', '+String(client.name).split(' ')[0]:'')+'! Tudo bem? ';if(pay){msg+=`Passando para lembrar da parcela ${pay.installment} de ${money(pay.amount)} do documento ${doc.number}, com vencimento em ${pay.due_date?new Date(pay.due_date+'T12:00:00').toLocaleDateString('pt-BR'):'a definir'}. Caso já tenha efetuado o pagamento, desconsidere. Qualquer dúvida estou à disposição. — ${local.company.name}`;}else if(doc.document_type==='proposal'){msg+=`Verifiquei que a proposta ${doc.number} enviada recentemente está em análise. Posso esclarecer alguma dúvida ou avançarmos com a contratação? — ${local.company.name}`;}else{msg+=`Gostaria de confirmar o recebimento e o aceite dos documentos ${doc.number}. Podemos finalizar essa etapa? — ${local.company.name}`;}if(ph)window.open('https://wa.me/'+ph+'?text='+encodeURIComponent(msg),'_blank');else toast('Cadastre o telefone do cliente para abrir o WhatsApp.');}
function pipelineBoard(){const cols=[{k:'draft',t:'Rascunho',arr:cache.proposals.filter(p=>(p.status||'draft')==='draft')},{k:'sent',t:'Aguardando cliente',arr:cache.proposals.filter(p=>p.status==='sent')},{k:'approved',t:'Aprovada',arr:cache.proposals.filter(p=>p.status==='approved')},{k:'contract',t:'Contrato ativo',arr:cache.contracts.filter(c=>c.status==='active')},{k:'os',t:'Ordem de Serviço',arr:(cache.orders||[]).filter(o=>o.status==='active'||o.status==='draft')},{k:'done',t:'Entregue',arr:[...(cache.terms||[]),...cache.contracts.filter(c=>c.status==='delivered')]}];return `<div class="pipeline">${cols.map(c=>`<div class="pipe-col"><div class="pipe-head ${c.k}">${c.t}<span>${c.arr.length}</span></div>${c.arr.slice(0,6).map(x=>`<button class="pipe-card" data-open="${esc(x.id)}"><strong>${esc(x.number)}</strong><span>${esc(x.client_name||'')}</span><em>${money(x.value)}${c.k==='done'&&x.created_at?' \u2022 '+new Date(x.created_at).toLocaleDateString('pt-BR'):''}</em>${validityExpired(x)?'<i class="pipe-warn">! validade vencida</i>':''}</button>`).join('')||'<div class="pipe-empty">—</div>'}</div>`).join('')}</div>`;}
function osTpl(o){return `<div class="paper-header"><img src="./assets/logo-agrageo_1.png" onerror="this.style.display='none'"><div><h2>AGRAGEO CONSULTORIA</h2><p>CNPJ ${esc(o.cnpj)} • ${esc(o.city)} • ${esc(o.phone)} • ${esc(o.email)}</p></div></div><h1 style="text-align:center;font-family:Georgia,serif;color:#b6811d;font-size:16px;letter-spacing:.05em;margin:28px 0 4px">ORDEM DE SERVIÇO / AUTORIZAÇÃO DE INÍCIO</h1><p style="text-align:center;margin:0"><span class="muted">${esc(o.number)} • Emitida em ${esc(o.date)}</span></p><h3>DADOS DO CONTRATO E CLIENTE</h3><table class="tbl" contenteditable="true"><tr><td>Contrato vinculado</td><td>${esc(o.origin)||'____________'}</td></tr><tr><td>Cliente</td><td>${esc(o.clientName)}${o.clientDoc?' — '+esc(o.clientDoc):''}</td></tr><tr><td>Serviço</td><td>${esc(o.service)}</td></tr><tr><td>Objeto resumido</td><td>${esc(o.scope)||'Conforme escopo do contrato/proposta de origem.'}</td></tr></table>${o.fichas&&o.fichas.length?'<h3>FICHAS TÉCNICAS DOS SERVIÇOS</h3>'+o.fichas.map(f=>`<div class="svc-block" contenteditable="true"><h4>${esc(f.name)}</h4>${fichaHtml(f)}</div>`).join(''):''}${acHtml({...o,type:'work_order'})}${eviPrintHtml(o)}<h3>AUTORIZAÇÃO DE INÍCIO</h3><div class="editor" contenteditable="true">Fica autorizada a execução dos serviços acima descritos, declarando o CONTRATANTE que: (i) efetuou o pagamento da parcela inicial conforme ajustado; (ii) disponibilizou toda a documentação necessária (matrícula, IPTU, projetos e demais documentos pertinentes); e (iii) garantiu o acesso ao imóvel nas datas previstas. Com o cumprimento dessas condições, inicia-se a contagem do prazo de execução (${esc(o.deadline)||'conforme contrato'}).</div><h3>OBSERVAÇÕES DE CAMPO</h3><div class="editor" contenteditable="true">Restrições de acesso, pontos de referência disponíveis, confrontantes informados pelo cliente e outras condições relevantes para a equipe de campo podem ser anotadas aqui.</div>${localDataLine(o.city)}<h3>ASSINATURAS</h3>${signatureBlock(o.clientName||'CONTRATANTE','Solicitação/Autorização de início','CPF/CNPJ: ____________',o.company,'CONTRATADA','CNPJ: '+o.cnpj)}${signatureBlock('ALEX DA SILVA AGRA','Coordenação da execução · RESPONSÁVEL TÉCNICO','Técnico em Geoprocessamento · Registro Nacional: 01039973183','','','')}`;}
function termTpl(o){return `<div class="paper-header"><img src="./assets/logo-agrageo_1.png" onerror="this.style.display='none'"><div><h2>AGRAGEO CONSULTORIA</h2><p>CNPJ ${esc(o.cnpj)} • ${esc(o.city)} • ${esc(o.phone)} • ${esc(o.email)}</p></div></div><h1 style="text-align:center;font-family:Georgia,serif;color:#b6811d;font-size:16px;letter-spacing:.05em;margin:28px 0 4px">TERMO DE ENTREGA E ACEITE DOS PRODUTOS</h1><p style="text-align:center;margin:0"><span class="muted">${esc(o.number)} • Emitido em ${esc(o.date)}</span></p><h3>DOCUMENTOS VINCULADOS</h3><table class="tbl" contenteditable="true"><tr><td>Contrato</td><td>${esc(o.origin)||'____________'}</td></tr><tr><td>Cliente</td><td>${esc(o.clientName)}${o.clientDoc?' — '+esc(o.clientDoc):''}</td></tr><tr><td>Serviço</td><td>${esc(o.service)}</td></tr></table>${o.fichas&&o.fichas.length?'<h3>SERVIÇOS CONCLUÍDOS</h3>'+o.fichas.map(f=>`<div class="svc-block" contenteditable="true"><h4>${esc(f.name)}</h4>${fichaHtml(f)}</div>`).join(''):''}${acHtml({...o,type:'delivery_term'})}<h3>PRODUTOS ENTREGUES</h3><ul class="li" contenteditable="true"><li>Planta georreferenciada (PDF/DWG);</li><li>Memorial descritivo (PDF);</li><li>Quadro de coordenadas (PDF/XLSX);</li><li>Arquivo vetorial (DWG/DXF/SHP), se previsto no escopo;</li><li>Relatório técnico (PDF);</li><li>ART/RRT, quando aplicável.</li></ul><h3>DECLARAÇÃO DE ENTREGA</h3><div class="editor" contenteditable="true">A AGRAGEO CONSULTORIA declara ter entregado, em meio digital, nesta data, todos os produtos técnicos previstos no contrato${o.origin?' '+esc(o.origin):''}, completos e conforme o escopo aprovado. O CONTRATANTE dispõe de 10 (dez) dias corridos para apontar desconformidades técnicas; findo esse prazo sem manifestação por escrito, os serviços serão considerados aceitos (Cláusula de Entrega e Aceite do contrato).</div><h3>ACEITE DO CONTRATANTE</h3><div class="editor" contenteditable="true">O CONTRATANTE declara receber os produtos listados e concorda com o encerramento do objeto contratual, ressalvadas as desconformidades eventualmente apontadas no prazo acima.</div>${localDataLine(o.city)}<h3>ASSINATURAS</h3>${signatureBlock(o.clientName||'CONTRATANTE','Recebimento e aceite','CPF/CNPJ: ____________',o.company,'CONTRATADA','CNPJ: '+o.cnpj)}${signatureBlock('ALEX DA SILVA AGRA','Encerramento técnico · RESPONSÁVEL TÉCNICO','Técnico em Geoprocessamento · Registro Nacional: 01039973183','','','')}`;}

function shell(h,b,a=''){return `<div class="section-head"><div><h2>${h}</h2><div class="muted">Gestão interna da Agrageo Consultoria</div></div>${a}</div>${b}`;}
function docTypeOf(x){return ['proposal','contract','work_order','delivery_term'].includes(x&&x.document_type)?x.document_type:'contract';}
function tableDocs(){const all=[...cache.proposals.map(x=>({...x,type:'Proposta'})),...cache.contracts.map(x=>({...x,type:'Contrato'})),...(cache.orders||[]).map(x=>({...x,type:'Ordem de Serviço'})),...(cache.terms||[]).map(x=>({...x,type:'Termo de Entrega'}))].sort((a,b)=>new Date(b.sent_at||b.created_at||0)-new Date(a.sent_at||a.created_at||0)).slice(0,15);if(!all.length)return '<div class="empty">Nenhum documento cadastrado ainda.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th data-sort="">Número</th><th data-sort="">Tipo</th><th data-sort="">Cliente</th><th data-sort="">Valor</th><th data-sort="">Status</th><th data-sort="">Data</th><th></th></tr></thead><tbody>${all.map(x=>`<tr><td><strong>${esc(x.number)}</strong>${validityExpired(x)?' <span class="badge expired" title="Validade vencida — reenvie ou renove a proposta">! validade vencida</span>':''}</td><td>${x.type}</td><td>${esc(x.client_name||'')}</td><td>${money(x.value)}</td><td><span class="badge ${x.status}">${statusLabel(x.status,docTypeOf(x))}</span></td><td>${esc((x.sent_at||x.created_at)?new Date(x.sent_at||x.created_at).toLocaleDateString('pt-BR'):'')}</td><td><button class="btn small" data-open="${esc(x.id||'')}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){const sentN=cache.proposals.filter(x=>x.status==='sent'||x.status==='approved').length,convN=cache.proposals.filter(x=>x.status==='converted').length,expN=cache.proposals.filter(validityExpired).length,osAtivas=(cache.orders||[]).filter(o=>['active','draft'].includes(o.status)).length,entregues=(cache.terms||[]).length,valorProp=cache.proposals.filter(x=>x.status!=='converted').reduce((a,b)=>a+Number(b.value||0),0),valorContr=cache.contracts.reduce((a,b)=>a+Number(b.value||0),0),valorEntregue=(cache.terms||[]).reduce((a,b)=>a+Number(b.value||0),0);const kpi=(l,v,f)=>`<div class="card"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div><div class="kpi-foot">${f||''}</div></div>`;const reqPend=(cache.requests||[]).filter(r=>['novo','em_analise'].includes(r.status||'novo')).length;return `<div class="grid kpis">${kpi('Clientes',cache.clients.length,'cadastrados')}${kpi('Solicitações novas',reqPend,reqPend?'clique em Solicitações →':'sem pendências')}${kpi('Propostas abertas',cache.proposals.filter(x=>x.status!=='converted').length,expN?expN+' com validade vencida':'no prazo')}${kpi('Enviadas / aguardando',sentN,'cliente analisando')}${kpi('Taxa de conversão',convN+sentN?Math.round(100*convN/(convN+sentN))+'%':'—','propostas enviadas → contrato')}${kpi('Contratos ativos',cache.contracts.filter(x=>x.status==='active').length,'em vigência')}${kpi('Ordens de Serviço ativas',osAtivas,'autorizadas a iniciar')}${kpi('Em execução',(cache.contracts.filter(c=>c.has_os&&c.status==='active').length+osAtivas),'serviços em campo')}${kpi('Entregues (termos assinados)',entregues,'objeto concluído')}${kpi('Valor em propostas',money(valorProp),'pipeline aberto')}${kpi('Contratos assinados',money(valorContr),'valor contratado')}${kpi('Processos públicos',(cache.processes||[]).filter(x=>!['concluido','arquivado'].includes(x.status)).length,'SEMA/INCRA/ANM/cartório — em acompanhamento')}${kpi('Recebido (parcelas)',money(cache.payments.filter(p=>p.paid_at).reduce((a,p)=>a+Number(p.amount||0),0)),'no Financeiro')}${kpi('Obrigações fiscais pendentes',fisBellItems().length,fisBellItems().length?'PGDAS-D, DCTFWeb… veja o sino 🔔':'tudo entregue no mês')}${kpi('Cancelados/expirados',cache.contracts.filter(x=>['cancelled','expired'].includes(x.status)).length+cache.proposals.filter(x=>x.status==='cancelled').length,'documentos perdidos')}</div><div class="grid" style="margin-top:16px"><div class="card">${shell('Pipeline comercial',pipelineBoard())}</div><div class="card" style="margin-top:16px">${alertsPanel()}</div><div class="card" style="margin-top:16px">${shell('Documentos recentes',tableDocs())}</div></div>`;}
function rowActions(kind,id){if(['proposals','contracts','orders','terms'].includes(kind)&&id)return `<div style="display:flex;gap:6px;justify-content:flex-end"><button class="btn small" data-open="${esc(id)}" title="Abrir">👁</button><button class="btn small" data-edit="${kind}:${esc(id)}" title="Editar">✎</button><button class="btn small" data-dup="${kind}:${esc(id)}" title="Duplicar">⧉</button><button class="btn small danger" data-del="${kind}:${esc(id)}" title="Excluir">🗑</button></div>`;if(!id)return '';return `<div style="display:flex;gap:6px;justify-content:flex-end"><button class="btn small" data-edit="${kind}:${esc(id)}" title="Editar">✎</button><button class="btn small danger" data-del="${kind}:${esc(id)}" title="Excluir">🗑</button></div>`;}
function filterBar(kind){const arr=cache[kind]||[];if(!['proposals','contracts','orders','terms','clients'].includes(kind)||!arr.length)return '';const st={},cts={};arr.forEach(x=>{st[x.status||'draft']=(st[x.status||'draft']||0)+1;if(kind==='clients'){const u=String(x.city||'').split('/').pop().trim().toUpperCase();if(u)cts[u]=(cts[u]||0)+1;}});let b='';if(st.active)b+=`<button class="fchip" data-fs="active">${kind==='clients'?'Com documentos ativos':'Ativos'} <b>${st.active}</b></button>`;if(st.draft)b+=`<button class="fchip" data-fs="draft">Rascunhos <b>${st.draft}</b></button>`;if(kind==='proposals'&&st.sent)b+=`<button class="fchip" data-fs="sent">Aguardando cliente <b>${st.sent}</b></button>`;if(kind==='proposals')b+='<button class="fchip" data-fs="_expired">\u26a0 Validade vencida</button>';if(st.cancelled)b+=`<button class="fchip" data-fs="cancelled">Cancelados <b>${st.cancelled}</b></button>`;Object.keys(cts).sort().slice(0,3).forEach(u=>{b+=`<button class="fchip uf" data-fs="uf:${esc(u)}">${esc(u)} <b>${cts[u]}</b></button>`;});return b?`<div class="chips">${b}</div>`:'';}
function applyListFilter(root){const act=root.querySelector('.chips .fchip.on'),q=((root.querySelector('[data-filter]')||{}).value||'').toLowerCase();root.querySelectorAll('tbody tr').forEach(r=>{const fv=r.dataset.fv||'';const okChip=!act||fv===act.dataset.fs||fv.split(' ')[0]===act.dataset.fs.split(':')[0];r.style.display=okChip&&(!q||r.innerText.toLowerCase().includes(q))?'':'none';});}
