function cftCodesFor(name){const n=(name||'').toLowerCase();const out=[];CFT_GROUPS.forEach(gr=>gr.items.forEach(it=>{const code=it.split(' ')[0],desc=it.slice(code.length+1).toLowerCase();if(desc&&n.includes(desc)&&!out.includes(it))out.push(it);}));return out;}
function rtLineHtml(){const p=(local.professionals||[])[0]||{};return p.name?`<span style="font-size:11px;color:#5b6b7d;display:block;margin-top:2px">${esc(p.titulo||'')} · Registro Nacional ${esc(p.registro||'')}${p.processo?' · Processo '+esc(p.processo):''}</span>`:'';}
function profCard(p,i){return `<div class="card" style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;align-items:start;gap:8px"><strong>${esc(p.name)}</strong><div style="display:flex;gap:6px"><button class="btn small" data-prof-edit="${i}" title="Editar">✎</button><button class="btn small danger" data-prof-del="${i}" title="Remover">🗑</button></div></div><div class="muted" style="margin-top:6px;font-size:12px">${esc(p.titulo||'')}${p.especializacao?' · '+esc(p.especializacao):''}${p.registro?' · Registro Nacional '+esc(p.registro)+(p.processo?' · Processo '+esc(p.processo):''):''}${p.cpf?' · CPF '+esc(p.cpf):''}${p.email?' · '+esc(p.email):''}</div>${p.atribuicao?`<div style="margin-top:8px;font-size:12px;color:#41546a">${esc(p.atribuicao)}</div>`:''}<details style="margin-top:10px"><summary style="cursor:pointer;font-size:12px;color:#b6811d;font-weight:700">📜 Atividades técnicas habilitadas (SIN-CRT)</summary><div style="max-height:320px;overflow:auto;margin-top:8px">${CFT_GROUPS.map(g=>`<div style="margin-bottom:8px"><div style="font-weight:700;font-size:11px;color:#5b6b7d;text-transform:uppercase">${esc(g.g)}</div>${g.items.map(it=>'<code style="margin:2px 3px 2px 0">'+esc(it)+'</code>').join('')}</div>`).join('')}</div></details><details style="margin-top:6px"><summary style="cursor:pointer;font-size:12px;color:#b6811d;font-weight:700">⛏️ Atividades específicas Geologia/Minas (CREA-MT — códigos W)</summary><div style="max-height:320px;overflow:auto;margin-top:8px">${GEO_W.map(it=>'<div style="font-size:11px;padding:1px 0"><code>'+it[0]+'</code> '+esc(it[1])+'</div>').join('')}</div></details></div>`;}
function profForm(i){const arr=local.professionals||(local.professionals=[]),rec=(i!=null?arr[i]:null)||null;modalBox(rec?'Editar profissional':'Novo profissional',`<form id="prof-form"><div class="form-grid"><div class="field full"><label>Nome</label><input class="input" name="name" required value="${esc(rec?.name)}"></div><div class="field"><label>CPF</label><input class="input" name="cpf" value="${esc(rec?.cpf)}"></div><div class="field"><label>Registro Nacional (SIN-CRT)</label><input class="input" name="registro" value="${esc(rec?.registro)}"></div><div class="field"><label>Processo de registro</label><input class="input" name="processo" value="${esc(rec?.processo)}"></div><div class="field"><label>Tipo / classe</label><input class="input" name="tipo_registro" placeholder="Definitivo / ATIVO" value="${esc([rec?.tipo_registro,rec?.classe_registro].filter(Boolean).join(' · '))}"></div><div class="field full"><label>Título profissional</label><input class="input" name="titulo" placeholder="Ex.: TÉCNICO EM GEOPROCESSAMENTO" value="${esc(rec?.titulo)}"></div><div class="field"><label>Especialização</label><input class="input" name="especializacao" value="${esc(rec?.especializacao)}"></div><div class="field"><label>E-mail</label><input class="input" name="email" type="email" value="${esc(rec?.email)}"></div><div class="field full"><label>Atribuições legais</label><textarea class="textarea" name="atribuicao" style="min-height:110px">${esc(rec?.atribuicao)}</textarea></div></div></form>`,()=>{const f=document.getElementById('prof-form');const d=Object.fromEntries(new FormData(f));const parts=String(d.tipo_registro||'').split('·');const obj={...(rec||{}),...d,tipo_registro:(parts[0]||'').trim(),classe_registro:(parts[1]||'').trim()};if(rec)arr[i]=obj;else arr.push(obj);saveLocal();modal.innerHTML='';toast('Profissional salvo.');render(view);});}
