function svcExists(name){return (cache.services||[]).some(x=>String(x.name||'').trim().toLowerCase()===String(name).trim().toLowerCase());}
// ── Serviços cadastrados organizados por profissão/subcategoria (espelho do catálogo) ──
const CAT_PROFS=['GEOLOGIA','MEIO AMBIENTE','GEOPROCESSAMENTO / SR','TOPOGRAFIA / GEODÉSIA'];
// ── Modo de execução do projeto: PRÓPRIO = Agrageo executa com RT próprio; GERENCIADO = projeto multidisciplinar — a Agrageo coordena/gerencia, etapas de outras profissões ficam com parceiros/terceirizados habilitados ──
const EXEC_ICONE={PRÓPRIO:'🔧',GERENCIADO:'🧭'};
function isManaged(s){return /gerenc|coorden/i.test(String((s&&s.responsible)||''));}
function execModeOf(ids){const list=(ids||[]).map(id=>(cache.services||[]).find(x=>String(x.id)===String(id))).filter(Boolean);if(!list.length)return 'PRÓPRIO';return list.some(isManaged)?'GERENCIADO':'PRÓPRIO';}
function execBlock(cur){const v=cur||'PRÓPRIO';return `<div class="field full"><label>Modo de execução do projeto <span class="muted" style="font-weight:400">(aparece na capa e nas fichas dos documentos)</span></label><select class="select" name="exec_mode"><option value="PRÓPRIO"${v==='PRÓPRIO'?' selected':''}>🔧 Execução própria — Agrageo executa tudo com seu responsável técnico</option><option value="GERENCIADO"${v==='GERENCIADO'?' selected':''}>🧭 Gerenciamento / coordenação de projeto multidisciplinar — Agrageo gerencia o projeto e contrata parceiros/terceirizados habilitados para as etapas de outras profissões</option></select></div>`;}
function selNames(f){return [...f.querySelectorAll('.svc-checks input:checked')].map(c=>((cache.services||[]).find(s=>String(s.id)===c.value)||{}).name).filter(Boolean).join('; ');}
function execLineHtml(o){return o.execMode==='GERENCIADO'?`<div class="exec-banner" contenteditable="true">🧭 <strong>PROJETO MULTIDISCIPLINAR — GERENCIADO PELA AGRAGEO CONSULTORIA.</strong> A AGRAGEO atua como coordenadora/gerenciadora do projeto, respondendo pela gestão técnica, documental e operacional. As etapas que exigem habilitação de outras profissões regulamentadas (ex.: biólogo, engenheiro florestal/agrônomo/civil, laboratórios) são executadas por parceiros devidamente habilitados, cada qual responsável técnica e legalmente por sua parte; os serviços próprios da Agrageo são assinados pelo seu responsável técnico.</div>`:'';}
function fichaExecBadge(f){return f.managed?'<span class="badge cancelled" title="Etapa executada por parceiro habilitado — projeto gerenciado pela Agrageo">Terceirizável · Gerência Agrageo</span>':'';}
// ── Acompanhamento periódico: serviços que exigem monitorar prazos/análises de órgãos (SEMAs, INCRA, cartórios, ANM...) ou condicionantes. Editável no documento e removível pelo botão ✕; valor estimado entra na proposta junto com os serviços marcados ──
const AC_FREQ=[['','— sem acompanhamento —'],['mensal','Mensal'],['bimestral','Bimestral'],['trimestral','Trimestral'],['semestral','Semestral'],['anual','Anual'],['ate_deferimento','Até o deferimento do órgão']];
const acLbl=v=>(AC_FREQ.find(x=>x[0]===v)||['',''])[1]||'';
function acFormRow(a,i){a=a||{};return `<div class="ac-row"><input class="input" name="ac_desc_${i}" placeholder="Ex.: Acompanhamento do processo de licenciamento na SEMA-MT" value="${esc(a.desc)}"><select class="select" name="ac_freq_${i}">${AC_FREQ.map(([v,l])=>`<option value="${v}"${a.freq===v?' selected':''}>${l}</option>`).join('')}</select><input class="input" type="number" step=".01" min="0" name="ac_val_${i}" placeholder="Valor estimado (R$)" value="${Number(a.value)>0?Number(a.value):''}"><button type="button" class="icon-btn ac-del" title="Remover este acompanhamento">×</button></div>`;}
function acFormBlock(list){const arr=(list&&list.length)?list:[{}];return `<div class="field full"><label>Acompanhamento periódico <span class="muted" style="font-weight:400">(monitorar protocolos/análises de órgãos, condicionantes, validades — opcional; use × para remover)</span></label><div id="ac-wrap">${arr.map((a,i)=>acFormRow(a,i)).join('')}</div><button type="button" class="btn small" id="ac-add">＋ Adicionar acompanhamento</button></div>`;}
function bindAcForm(f){const w=f.querySelector('#ac-wrap');if(!w)return;const re=()=>{w.querySelectorAll('.ac-del').forEach(b=>b.onclick=()=>{if(w.querySelectorAll('.ac-row').length>1)b.closest('.ac-row').remove();else b.closest('.ac-row').querySelectorAll('input,select').forEach(x=>{if(x.tagName==='SELECT')x.selectedIndex=0;else x.value='';});});};w.parentElement.querySelector('#ac-add').onclick=()=>{w.insertAdjacentHTML('beforeend',acFormRow({},Date.now()));re();};re();}
function readAcForm(f){return [...f.querySelectorAll('.ac-row')].map(r=>({desc:String(r.querySelector('[name^=ac_desc]').value||'').trim(),freq:r.querySelector('[name^=ac_freq]').value,value:Number(r.querySelector('[name^=ac_val]').value||0)||0})).filter(a=>a.desc||(a.freq&&a.value));}
// ── Etapas do projeto (linha do tempo sequencial + tabela de composição com executor/prazo/qtd/valor) — estrutura dos modelos antigos da Agrageo; tudo editável e removível ──
function etFormRow(e,i){e=e||{};return `<div class="et-row" style="display:grid;grid-template-columns:2fr 1fr .8fr .5fr .8fr auto;gap:6px;margin-bottom:6px"><input class="input" name="et_desc_${i}" placeholder="Ex.: Levantamento Planialtimétrico e Georreferenciamento" value="${esc(e.desc)}"><input class="input" name="et_exec_${i}" placeholder="Executor" value="${esc(e.executor||'Agrageo')}"><input class="input" name="et_prazo_${i}" placeholder="Prazo (ex.: 3 dias úteis)" value="${esc(e.prazo)}"><input class="input" name="et_qtd_${i}" placeholder="Qtd" value="${Number(e.qty)>0?Number(e.qty):''}"><input class="input" type="number" step=".01" min="0" name="et_val_${i}" placeholder="Valor (R$)" value="${Number(e.value)>0?Number(e.value):''}"><button type="button" class="icon-btn et-del" title="Remover esta etapa">×</button></div>`;}
function etFormBlock(list){const arr=(list&&list.length)?list:[];return `<div class="field full"><label>Etapas do projeto <span class="muted" style="font-weight:400">(linha do tempo e composição do investimento — opcional; os valores somam no total sugerido)</span></label><div id="et-wrap">${arr.map((e,i)=>etFormRow(e,i)).join('')}</div><button type="button" class="btn small" id="et-add">＋ Adicionar etapa</button></div>`;}
function bindEtForm(f){const w=f.querySelector('#et-wrap');if(!w)return;const re=()=>{w.querySelectorAll('.et-del').forEach(b=>b.onclick=()=>b.closest('.et-row').remove());};re();const add=f.querySelector('#et-add');if(add)add.onclick=()=>{w.insertAdjacentHTML('beforeend',etFormRow({},w.querySelectorAll('.et-row').length));re();};}
function readEtForm(f){return [...f.querySelectorAll('.et-row')].map(r=>({desc:String(r.querySelector('[name^=et_desc]').value||'').trim(),executor:String(r.querySelector('[name^=et_exec]').value||'').trim()||'Agrageo',prazo:String(r.querySelector('[name^=et_prazo]').value||'').trim(),qty:Number(r.querySelector('[name^=et_qtd]').value||0)||0,value:Number(r.querySelector('[name^=et_val]').value||0)||0})).filter(e=>e.desc);}
function etSum(o){return (o.etapas||[]).reduce((s,e)=>s+(Number(e.value)||0),0);}
function ET_PHASES(svcName,cat){const n=String(svcName||'').toLowerCase(),c=String(cat||'').toUpperCase();if(/documenta|an[áa]lise|diagn[óo]stic|consulta pr[eé]via|planejamento|loca[çc][ãa]o.*po[çc]o|vulnerab/.test(n+' '+c))return 'Fase 1 – Escritório/Diagnóstico';if(/campo|levantamento|sondagem|teste|coleta|monitoramento|ensaio|demarca[çc]|resgate|instrumenta/.test(n))return 'Fase 2 – Campo';if(/processamento|modelo digital|mapa|cartograf|\bsig\b|sensoriamento|imagem|classifica[çc]|ortofoto|fotogrametria|planta|memorial|curvas de n[íi]vel|geoprocessamento/.test(n+' '+c))return 'Fase 3 – Processamento/Documentação';if(/protocolo|outorga|licenciamento|acompanhamento|regulariza[çc]|certifica[çc]|sigef|incra|\bart\b|emiss[ãa]o|entrega/.test(n))return 'Fase 4 – Protocolo/Encerramento';return 'Fase 1 – Escritório/Diagnóstico';}
function etHtml(o){if(!(o.etapas&&o.etapas.length))return '';const byPhase={};(o.fichas||[]).forEach(f=>{const k=ET_PHASES(f.name,f.category);(byPhase[k]=byPhase[k]||[]).push(f.name);});const order=['Fase 1 – Escritório/Diagnóstico','Fase 2 – Campo','Fase 3 – Processamento/Documentação','Fase 4 – Protocolo/Encerramento'];const phases=order.filter(k=>byPhase[k]&&byPhase[k].length);return `<h3>5. COMPOSIÇÃO DOS SERVIÇOS E INVESTIMENTO</h3><div class="editor" contenteditable="true">Os serviços estão estruturados em etapas que integram atividades de escritório, campo, acompanhamento e encerramento. Cada etapa possui executor definido (Agrageo ou terceiros habilitados), prazo estimado e valor correspondente. O investimento total reflete apenas os serviços descritos no escopo, não incluindo taxas públicas ou serviços adicionais de terceiros.</div>${phases.length?'<p style="margin:14px 0 4px"><strong>Linha do Tempo — execução sequencial por fases</strong></p><ul class="li" contenteditable="true">'+phases.map((k,i)=>'<li>'+('<strong>'+k+(byPhase[k].length?':':'')+'</strong> ')+byPhase[k].map(esc).join('; ')+'</li>').join('')+'</ul>':''}<table class="tbl" contenteditable="true"><tr><th>Nº</th><th>Etapa / Serviço</th><th>Executor</th><th>Prazo</th><th>Qtd.</th><th>Valor</th></tr>${o.etapas.map((e,i)=>`<tr><td>${i+1}</td><td>${esc(e.desc)}</td><td>${esc(e.executor)||'Agrageo'}</td><td>${esc(e.prazo)||'—'}</td><td>${Number(e.qty)||1}</td><td>${Number(e.value)>0?money(Number(e.value)):'a definir'}</td></tr>`).join('')}<tr><td colspan="5" style="text-align:right"><strong>VALOR TOTAL DAS ETAPAS:</strong></td><td><strong>${etSum(o)>0?money(etSum(o)):'R$ 0,00 — a distribuir'}</strong></td></tr></table><p class="muted" contenteditable="true">Observação: os valores acima compõem o investimento total indicado na seção ${9+(o.etapas&&o.etapas.length?1:0)}; a distribuição interna por etapa é comercial e poderá ser ajustada sem alteração do valor total, desde que mantido o escopo contratado. A Agrageo acompanha as movimentações disponibilizadas pelos órgãos, mas não controla fila, prazos, decisões ou atualizações internas destes.</p>`;}
const AC_H='ACOMPANHAMENTO PERIÓDICO',AC_ON=o=>o&&o.acompanhamento&&o.acompanhamento.length;function acN(v,o){return v+(AC_ON(o)?1:0);}function secN(v,o){return v+(o&&o.etapas&&o.etapas.length?1:0)+(AC_ON(o)?1:0);}function acHtml(o){return AC_ON(o)?`<h3>${9+(o.etapas&&o.etapas.length?1:0)}. ${AC_H}</h3><table class="tbl" contenteditable="true"><tr><th>Serviço / objeto do acompanhamento</th><th>Frequência</th><th>Valor estimado</th></tr>${o.acompanhamento.map(a=>`<tr><td>${esc(a.desc)||'____________'}</td><td>${esc(acLbl(a.freq))||'____________'}</td><td>${Number(a.value)>0?money(Number(a.value)):'a combinar'}</td></tr>`).join('')}</table><p class="muted" contenteditable="true">O acompanhamento periódico compreende a verificação de andamento de protocolos e análises junto aos órgãos competentes (SEMA/SEDUR/municipais, INCRA/SIGEF, cartórios, ANM e demais), controle de condicionantes e validades, comunicações ao CONTRATANTE e renovações necessárias, não incluindo novos trabalhos técnicos de campo ou peças não previstas no escopo.</p>`:'';}
function acSum(o){return (o.acompanhamento||[]).reduce((s,a)=>s+(Number(a.value)||0),0);}
