async function catalogInsertOne(i){const s=SERVICES_CATALOG[i];if(!s)return false;if(svcExists(s.name)){toast('Este serviço já está cadastrado.');return false;}const extra=cftCodesFor(s.name).map(it=>it.split(' ')[0]).concat(wCodesFor(s.name).map(it=>it[0])).filter(c=>!s.codes.some(x=>x.toUpperCase().includes(String(c).toUpperCase())));try{const saved=await insert('services',{name:s.name,description:s.desc,default_scope:s.desc,codes:[...s.codes,...extra].join(', '),category:s.prof+' — '+s.sub,responsible:s.resp==='T'?'Parceiro / Terceirizado (gerência Agrageo)':'Agrageo (RT próprio)'},'services');cache.services.unshift(saved);return true;}catch(e){return false;}}
function importCatalog(){modalBox('Catálogo de serviços por profissão — Geólogo (CFO/CREA-MT), Meio Ambiente, Geoprocessamento/SR e Topografia (CFT)',`<p class="muted">Escolha a <strong>aba da profissão</strong>, revise as subcategorias e adicione os serviços que a Agrageo executa. Itens marcados <strong>Terceirizável</strong> são multidisciplinares: a execução vai para parceiro enquanto você gerencia o projeto. Os <strong>códigos</strong> aparecem na ficha do serviço e podem ser ajustados manualmente ao editar.</p><div style="display:flex;gap:8px;align-items:center;margin-bottom:6px"><button class="btn primary" id="svc-import-all">⬇ Importar todos</button><span class="help" style="margin:0">Ou adicione um a um pelos botões abaixo.</span></div>${profTabs('all')}<div id="svc-grid"></div>`,async()=>{});const rerender=p=>{const g=document.getElementById('svc-grid');if(g)g.innerHTML=servicesGrid(p);document.querySelectorAll('#svc-profs .fchip').forEach(ch=>{ch.classList.toggle('on',ch.dataset.prof===p);ch.onclick=()=>rerender(ch.dataset.prof);});document.querySelectorAll('[data-svc-add]').forEach(b=>b.onclick=async()=>{if(await catalogInsertOne(Number(b.dataset.svcAdd))){b.textContent='✔ Já cadastrado';b.disabled=true;b.classList.remove('primary');}});};rerender('all');document.getElementById('svc-import-all').onclick=async(e)=>{e.target.disabled=true;let n=0;for(let i=0;i<SERVICES_CATALOG.length;i++){if(svcExists(SERVICES_CATALOG[i].name))continue;try{if(await catalogInsertOne(i))n++;}catch(err){break;}}modal.innerHTML='';toast(n?`${n} serviço(s) adicionados ao catálogo.`:'Todos os serviços já estavam cadastrados.');render('servicos');bind();};}
