function fisDueDate(rec,ym){const parts=String(ym||'').split('-');const d=new Number(rec.due_day||5);return new Date(Number(parts[0]),Number(parts[1])-1,Math.min(d,new Date(Number(parts[0]),Number(parts[1]),0).getDate()),12,0,0)}
