function fisStatusOf(rec,ym){const st=(rec.done||{})[ym];if(st)return{st,k:st==='pago'?'ok':st==='sem_movimento'?'sm':'done'};const due=fisDueDate(rec,ym),now=new Date();if(now>due)return{st:'vencida',k:'late'};const days=Math.ceil((due-now)/864e5);if(days<=7)return{st:'próxima',k:'soon',days,due};return{st:'no prazo',k:'ok_future',days,due}}
function fisBellItems(){const out=[];(cache.fiscal||[]).filter(r=>r.active!==false&&r.period==='M').forEach(r=>{[-1,0].forEach(off=>{const ym=fisYM(off),s=fisStatusOf(r,ym);if(s.k==='late')out.push({rec:r,ym,s,level:'late'});else if(s.k==='soon')out.push({rec:r,ym,s,level:'soon'})})});return out.sort((a,b)=>a.level===b.level?new Date(a.ym)-new Date(b.ym):(a.level==='late'?-1:1))}
