function fisForm(rec){const isNew=!rec;modalBox(isNew?'Nova obrigação tributária':'Editar obrigação',`<form id="fis-form"><div class="form-grid"><div class="field full"><label>Nome da obrigação *</label><input class="input" name="name" required value="${esc(rec?.name)}" placeholder="Ex.: PGDAS-D mensal"></div><div class="field"><label>Órgão</label><input class="input" name="organ" value="${esc(rec?.organ)}" placeholder="Receita Federal / SEMFAZ ..."></div><div class="field"><label>Dia do vencimento</label><input class="input" name="due_day" type="number" min="1" max="31" value="${esc(rec?.due_day??5)}"></div><div class="field"><label>Periodicidade</label><select class="input" name="period"><option value="M"${(rec?.period||'M')==='M'?' selected':''}>Mensal</option><option value="T"${rec?.period==='T'?' selected':''}>Trimestral</option><option value="A"${rec?.period==='A'?' selected':''}>Anual</option></select></div><div class="field"><label>Situação</label><select class="input" name="active"><option value="1"${rec?.active!==false?' selected':''}>Ativa (recebe alertas)</option><option value="0"${rec?.active===false?' selected':''}>Pausada</option></select></div><div class="field full"><label>Observações / como cumprir</label><textarea class="textarea" name="obs" style="min-height:90px">${esc(rec?.obs)}</textarea></div></div></form>`,()=>{const d=Object.fromEntries(new FormData(document.getElementById('fis-form')));const obj={...(rec||{id:crypto.randomUUID(),done:{},created_at:new Date().toISOString()}),name:d.name.trim(),organ:d.organ.trim(),due_day:Number(d.due_day)||5,period:d.period,active:d.active==='1',obs:d.obs.trim()};saveFiscal(obj);modal.innerHTML='';toast('Obrigação salva.');render(view);});}
function fisList(){const arr=cache.fiscal||[],months=[fisYM(-1),fisYM(0),fisYM(1)],pend=fisBellItems().length;const kpi=(l,v,f)=>`<div class="card"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div><div class="kpi-foot">${f||''}</div></div>`;const rowsHtml=arr.map(r=>{const cells=months.map(ym=>{const s=fisStatusOf(r,ym);const dt=fisDueDate(r,ym).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});if(s.st==='pago'||s.st==='sem_movimento'||(s.st&&s.st!=='vencida'&&s.st!=='próxima'&&s.st!=='no prazo'))return `<button class="btn small ok" data-fis-mark="${esc(r.id)}:${ym}:pago" title="Clique para desfazer">✔ ${esc(s.st==='pago'?'Pago':s.st==='sem_movimento'?'Sem movimento':esc(s.st))}</button>`;const cls=s.k==='late'?'danger':s.k==='soon'?'warn':'ghost';return `<span class="badge ${cls}" title="Vence em ${dt}">${dt}${s.k==='late'?' • vencida':s.k==='soon'?' • em '+s.days+'d':''}</span> <button class="btn small" data-fis-mark="${esc(r.id)}:${ym}:pago">✔ Pago</button><button class="btn small" data-fis-mark="${esc(r.id)}:${ym}:sem_movimento" title="Entregar sem movimento / zerada">∅ Sem mov.</button>`}).join('<br>');return `<tr><td><strong>${esc(r.name)}</strong>${r.organ?`<div class="muted">${esc(r.organ)}</div>`:''}${r.obs?`<details class="fis-obs"><summary>Como cumprir</summary><div class="muted">${esc(r.obs)}</div></details>`:''}</td><td>${r.active===false?'<span class="badge cancelled">pausada</span>':'<span class="badge active">ativa</span>'}</td><td>dia ${Number(r.due_day)||5}</td><td>${fisPeriodLabel(r.period)}</td><td style="white-space:nowrap">${cells}</td><td style="white-space:nowrap"><button class="btn small" data-fis-edit="${esc(r.id)}">✎</button><button class="btn small danger" data-fis-del="${esc(r.id)}">🗑</button></td></tr>`}).join('');return shell('Obrigações tributárias 🧾','<div class="grid kpis" style="margin-bottom:14px">'+kpi('Pendências urgentes',pend,pend?'veja o sino 🔔 acima':'tudo em dia')+kpi('Obrigações ativas',arr.filter(r=>r.active!==false).length,'mensais/anuais')+kpi('Mês atual',fisYM(0),'referência dos alertas')+'</div><div class="alert-box info">🔔 O sino avisa todos os dias quando faltar ≤ 7 dias para o vencimento (ex.: PGDAS-D vence dia 05). Mesmo em mês <strong>sem movimento</strong>, registre "∅ Sem mov." — a entrega da declaração zerada continua obrigatória.</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Obrigação</th><th>Situação</th><th>Venc.</th><th>Per.</th><th>Mês anterior • atual • próximo</th><th></th></tr></thead><tbody>'+rowsHtml+'</tbody></table></div></div>',`<button class="btn primary" data-new="fiscal">＋ Nova obrigação</button>`);}
function nextProcNumber(){const y=new Date().getFullYear(),arr=cache.processes||[],maxNum=arr.reduce((m,x)=>{const mm=String(x.number||'').match(/(\d+)\s*$/);return Math.max(m,mm?Number(mm[1]):0);},0);return 'PROC-'+y+'-'+String(maxNum+1).padStart(4,'0');}
function procForm(existing){const rec=existing||null;const clOpts=cache.clients.map(x=>`<option value="${esc(x.id)}"${rec&&String(rec.client_id)===x.id?' selected':''}>${esc(x.name)}</option>`).join('');const docOpts=allDocs().filter(d=>['contract','proposal'].includes(d.document_type)).map(x=>`<option value="${esc(x.id)}"${rec&&String(rec.document_id)===x.id?' selected':''}>${esc(x.number)} — ${esc(x.client_name||'')}</option>`).join('');const stOpts=Object.entries(PROC_STATUS).map(([v,l])=>`<option value="${v}"${(rec?.status||'andamento')===v?' selected':''}>${l}</option>`).join('');modalBox(rec?('Editar processo '+esc(rec.number||'')):'Novo processo público',`<form id="proc-form"><div class="form-grid"><div class="field full"><label>Título * (ex.: Outorga poço tubular — Fazenda Santa Luzia)</label><input class="input" name="title" required value="${esc(rec?.title)}"></div><div class="field"><label>Órgão</label><input class="input" name="organ" placeholder="SEMA-MT / INCRA / ANM / Cartório RI…" value="${esc(rec?.organ)}"></div><div class="field"><label>Tipo de processo</label><select class="select" name="kind">${PROC_KINDS.map(k=>`<option${(rec?.kind||PROC_KINDS[0])===k?' selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Nº do protocolo no órgão</label><input class="input" name="protocol" placeholder="Ex.: 2026.12345/SEMA" value="${esc(rec?.protocol)}"></div><div class="field"><label>Status</label><select class="select" name="status">${stOpts}</select></div><div class="field"><label>Cliente</label><select class="select" name="client_id"><option value="">Selecione</option>${clOpts}</select></div><div class="field"><label>Vincular a documento</label><select class="select" name="document_id"><option value="">— nenhum —</option>${docOpts}</select></div><div class="field"><label>Próxima ação / conferência em</label><input class="input" type="date" name="next_action_date" value="${esc(rec?.next_action_date||'')}"></div><div class="field full"><label>Observações / exigências recebidas</label><textarea class="textarea" name="notes" placeholder="Descreva pendências, documentos exigidos pelo órgão, valores de taxas…">${esc(rec?.notes)}</textarea></div></div></form>`,async()=>{const f=document.getElementById('proc-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));const hist=(Array.isArray(rec?.history)?rec.history.slice():[]);hist.unshift({at:new Date().toISOString().slice(0,10),text:`Status: ${PROC_STATUS[d.status]||d.status}${d.protocol?' • Protocolo: '+d.protocol:''}${d.notes?' • '+d.notes:''}`});const payload={title:d.title,organ:d.organ,kind:d.kind,protocol:d.protocol,status:d.status,client_id:d.client_id||null,document_id:d.document_id||null,next_action_date:d.next_action_date||null,notes:d.notes,history:hist.slice(0,30),number:rec?.number||nextProcNumber()};try{const saved=await saveProcess({...payload,id:rec?.id});const i=(cache.processes||[]).findIndex(x=>String(x.id)===String(saved.id));if(i>=0)cache.processes[i]={...cache.processes[i],...payload,...saved};else{(cache.processes=cache.processes||[]).unshift({...payload,...saved});}modal.innerHTML='';toast('Processo salvo.');render(view);bind();}catch(e){}});}
function procList(){const arr=cache.processes||[],pend=arr.filter(p=>!['concluido','arquivado'].includes(p.status)).length,stale=arr.filter(p=>!['concluido','arquivado'].includes(p.status)&&p.last_checked_at&&(Date.now()-new Date(p.last_checked_at).getTime())>7*864e5).length,dueSoon=arr.filter(p=>p.next_action_date&&new Date(p.next_action_date)<=new Date(Date.now()+7*864e5)&&!['concluido','arquivado'].includes(p.status)).length;const kpi=(l,v,f)=>`<div class="card"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div><div class="kpi-foot">${f||''}</div></div>`;const body=arr.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Processo</th><th>Órgão</th><th>Protocolo</th><th>Última consulta</th><th>Próxima ação</th><th>Status</th><th></th></tr></thead><tbody>${arr.map(x=>{const cl=cache.clients.find(c=>String(c.id)===String(x.client_id));const last=x.last_checked_at?new Date(x.last_checked_at).toLocaleDateString('pt-BR'):'—';const staleRow=!['concluido','arquivado'].includes(x.status)&&(!x.last_checked_at||(Date.now()-new Date(x.last_checked_at).getTime())>7*864e5);return `<tr><td><strong>${esc(x.number)}</strong></td><td><strong>${esc(x.title)}</strong><br><span class="muted">${esc(cl?.name||'')}${x.kind?' • '+esc(x.kind):''}</span></td><td>${esc(x.organ||'')}</td><td>${esc(x.protocol||'—')}</td><td>${last}${staleRow?' <span class="badge expired">sem atualização há +7 dias</span>':''}</td><td>${x.next_action_date?new Date(x.next_action_date+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</td><td><button class="btn small status-btn" data-proc-status="${esc(x.id)}">${PROC_STATUS[x.status]||x.status} ▾</button></td><td>${rowActions('processes',x.id)}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty">Nenhum processo público acompanhado ainda.<br><button class="btn primary" style="margin-top:10px" data-new="processo">＋ Criar primeiro processo</button></div>`;return shell('Processos públicos em órgãos','<div class="grid kpis">'+kpi('Abertos',pend,'em andamento/exigência')+kpi('Concluídos',arr.filter(p=>p.status==='concluido').length,'deferidos')+kpi('Precisam ser consultados',stale,'sem verificação há +7 dias')+kpi('Ações desta semana',dueSoon,'próximas conferências')+'</div><div class="card" style="margin-top:16px">'+body+'</div>',`<button class="btn primary" data-new="processo">＋ Novo processo</button>`);}
function procStatusPicker(id){const p=(cache.processes||[]).find(x=>String(x.id)===String(id));if(!p)return;const opts=Object.entries(PROC_STATUS).map(([v,l])=>`<option value="${v}"${p.status===v?' selected':''}>${l}</option>`).join('');modalBox('Status do processo '+esc(p.number||''),`<div class="field"><label>Status</label><select class="select" id="ps-sel">${opts}</select></div><div class="field" style="margin-top:12px"><label>Anotação da movimentação (opcional)</label><input class="input" id="ps-note" placeholder="Ex.: protocolada resposta à exigência 02"></div>`,async()=>{const sel=document.getElementById('ps-sel').value,note=document.getElementById('ps-note').value.trim();const hist=(Array.isArray(p.history)?p.history.slice():[]);hist.unshift({at:new Date().toISOString().slice(0,10),text:`Status → ${PROC_STATUS[sel]}${note?' • '+note:''}`});p.status=sel;p.history=hist.slice(0,30);p.last_checked_at=new Date().toISOString();try{await saveProcess(p);modal.innerHTML='';toast('Processo atualizado.');render(view);bind();}catch(e){}});}
function procCheck(id){const p=(cache.processes||[]).find(x=>String(x.id)===String(id));if(!p)return;p.last_checked_at=new Date().toISOString();saveProcess(p).then(()=>{toast('Consulta registrada hoje.');render(view);bind();}).catch(()=>{});}

// ── Rentabilidade por projeto: custos operacionais/parceiros gravados em documents.content.costs (sem tabela nova) ──
function costsFor(doc){return Array.isArray(doc&&doc.content&&doc.content.costs)?doc.content.costs:[];}
function costsSum(doc){return costsFor(doc).reduce((a,c)=>a+Number(c.value||0),0);}
function profitInfo(doc){const rev=Number(doc&&doc.value||0),cost=costsSum(doc);return {rev,cost,res:rev-cost,margin:rev>0?Math.round(100*(rev-cost)/rev):null};}
function costRowsHtml(list){return list.map((c,i)=>`<tr><td style="width:34%"><input class="input cost-desc" value="${esc(c.desc||'')}" placeholder="Ex.: parceiro biólogo, laboratório, diárias"></td><td style="width:22%"><input class="input cost-who" value="${esc(c.who||'')}" placeholder="Quem recebe"></td><td style="width:18%"><input class="input cost-value" type="number" min="0" step="0.01" value="${Number(c.value||0)}"></td><td><button type="button" class="btn small danger" data-cost-del="${i}">✕</button></td></tr>`).join('');}
function costBlockHtml(doc){const list=costsFor(doc);const p=profitInfo(doc);return `<div class="card section-card" id="cost-block"><h3>💸 Custos do projeto & rentabilidade <span class="muted" style="font-weight:400">(uso interno — não aparece no PDF enviado ao cliente)</span></h3><table class="table" id="cost-table"><thead><tr><th>Custo</th><th>Favorecido</th><th>Valor (R$)</th><th></th></tr></thead><tbody>${costRowsHtml(list)}</tbody></table><div style="display:flex;gap:10px;align-items:center;margin-top:10px;flex-wrap:wrap"><button type="button" class="btn small" id="cost-add">＋ Adicionar custo</button><span class="muted" id="cost-total">Receita ${money(p.rev)} • Custos ${money(p.cost)} • Resultado <strong>${money(p.res)}</strong>${p.margin!==null?' • Margem '+p.margin+'%':''}</span></div></div>`;}
function bindCostBlock(doc){const tbl=document.getElementById('cost-table');if(!tbl||!document.getElementById('cost-add'))return;const recalc=()=>{const rows=[...tbl.querySelectorAll('tbody tr')];const tot=rows.reduce((a,r)=>{const v=r.querySelector('.cost-value');return a+(v?(Number(v.value)||0):0);},0);const rev=Number(document.querySelector('#doc-value')?.value||document.querySelector('#os-form [name=value]')?.value||doc.value||0);const el=document.getElementById('cost-total');if(el)el.innerHTML=`Receita ${money(rev)} • Custos ${money(tot)} • Resultado <strong>${money(rev-tot)}</strong>${rev>0?' • Margem '+Math.round(100*(rev-tot)/rev)+'%':''}`;};tbl.addEventListener('input',recalc);const addBtn=document.getElementById('cost-add');if(addBtn)addBtn.onclick=()=>{tbl.querySelector('tbody').insertAdjacentHTML('beforeend',costRowsHtml([{desc:'',who:'',value:0}]));bindCostDel();recalc();};const bindCostDel=()=>{tbl.querySelectorAll('[data-cost-del]').forEach(b=>b.onclick=()=>{b.closest('tr').remove();recalc();});};bindCostDel();}
function readCosts(){const tbl=document.getElementById('cost-table');if(!tbl)return undefined;return [...tbl.querySelectorAll('tbody tr')].map(r=>({desc:String((r.querySelector('.cost-desc')||{}).value||'').trim(),who:String((r.querySelector('.cost-who')||{}).value||'').trim(),value:Number(((r.querySelector('.cost-value')||{}).value)||0)||0})).filter(c=>c.desc||c.who||c.value);}

// ── Etapas do projeto na TELA DO DOCUMENTO (proposta/contrato/OS abertos): bloco interno editável, com ＋ Adicionar etapa funcionando e valores somando no total ──
function etEditBlock(doc,type){const list=(doc&&doc.content&&Array.isArray(doc.content.etapas))?doc.content.etapas:[];return `<div class="card section-card" id="et-block"><h3>🧩 Etapas do projeto <span class="muted" style="font-weight:400">(uso interno — a linha do tempo e a tabela de composição já saem no PDF)</span></h3><table class="table" id="et-edit-table"><thead><tr><th>Etapa / Serviço</th><th>Executor</th><th>Prazo</th><th>Qtd.</th><th>Valor (R$)</th><th></th></tr></thead><tbody>${list.map((e,i)=>`<tr><td style="width:34%"><input class="input etx-desc" value="${esc(e.desc||'')}" placeholder="Ex.: Levantamento planialtimétrico"></td><td style="width:16%"><input class="input etx-exec" value="${esc(e.executor||'Agrageo')}"></td><td style="width:16%"><input class="input etx-prazo" value="${esc(e.prazo||'')}" placeholder="Ex.: 5 dias úteis"></td><td style="width:8%"><input class="input etx-qtd" type="number" min="0" value="${Number(e.qty)>0?Number(e.qty):''}"></td><td style="width:14%"><input class="input etx-val" type="number" min="0" step="0.01" value="${Number(e.value||0)}"></td><td><button type="button" class="btn small danger" data-etx-del="${i}">✕</button></td></tr>`).join('')}</tbody></table><div style="display:flex;gap:10px;align-items:center;margin-top:10px;flex-wrap:wrap"><button type="button" class="btn small" id="etx-add">＋ Adicionar etapa</button><span class="muted" id="etx-total">${list.length?'Total das etapas '+money(list.reduce((a,e)=>a+Number(e.value||0),0)):'Nenhuma etapa ainda — adicione abaixo ou preencha no formulário da proposta.'}</span></div></div>`;}
function bindEtEdit(doc){const tbl=document.getElementById('et-edit-table');if(!tbl)return;const recalc=()=>{const rows=[...tbl.querySelectorAll('tbody tr')];const tot=rows.reduce((a,r)=>a+(Number(r.querySelector('.etx-val').value)||0),0);const el=document.getElementById('etx-total');if(el)el.innerHTML=rows.length?'Total das etapas '+money(tot)+' • (reflexo no valor do documento: 💾 Salvar alterações)':'Nenhuma etapa ainda — adicione abaixo.';};tbl.addEventListener('input',recalc);const addBtn=document.getElementById('etx-add');if(addBtn)addBtn.onclick=()=>{tbl.querySelector('tbody').insertAdjacentHTML('beforeend','<tr><td style="width:34%"><input class="input etx-desc" placeholder="Ex.: Levantamento planialtimétrico"></td><td style="width:16%"><input class="input etx-exec" value="Agrageo"></td><td style="width:16%"><input class="input etx-prazo" placeholder="Ex.: 5 dias úteis"></td><td style="width:8%"><input class="input etx-qtd" type="number" min="0"></td><td style="width:14%"><input class="input etx-val" type="number" min="0" step="0.01"></td><td><button type="button" class="btn small danger" data-etx-del="0">✕</button></td></tr>');wireDel();recalc();toast('Etapa adicionada — preencha e clique em 💾 Salvar alterações.');};const wireDel=()=>{tbl.querySelectorAll('[data-etx-del]').forEach(b=>b.onclick=()=>{b.closest('tr').remove();recalc();});};wireDel();}
function readEtEdit(){const tbl=document.getElementById('et-edit-table');if(!tbl)return undefined;return [...tbl.querySelectorAll('tbody tr')].map(r=>({desc:String(r.querySelector('.etx-desc').value||'').trim(),executor:String(r.querySelector('.etx-exec').value||'').trim()||'Agrageo',prazo:String(r.querySelector('.etx-prazo').value||'').trim(),qty:Number(r.querySelector('.etx-qtd').value||0)||0,value:Number(r.querySelector('.etx-val').value||0)||0})).filter(e=>e.desc);}

// ── Evidências de campo (fotos/arquivos leves): gravadas em documents.content.evidences como dataURL comprimido — sem bucket novo ──
const eviFor=doc=>Array.isArray(doc&&doc.content&&doc.content.evidences)?doc.content.evidences:[];
function eviShrink(file){return new Promise((res,rej)=>{if(!/^image\//.test(file.type)){const r=new FileReader();r.onload=()=>res({name:file.name,type:file.type,dataUrl:String(r.result),at:new Date().toISOString()});r.onerror=rej;r.readAsDataURL(file);return;}const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const MAX=1280,sc=Math.min(1,MAX/Math.max(img.width,img.height)),w=Math.round(img.width*sc),h=Math.round(img.height*sc);const cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(img,0,0,w,h);URL.revokeObjectURL(url);res({name:file.name,type:'image/jpeg',dataUrl:cv.toDataURL('image/jpeg',0.72),at:new Date().toISOString()});};img.onerror=e=>{URL.revokeObjectURL(url);rej(e);};img.src=url;});}
function eviBlockHtml(doc){const list=eviFor(doc);return `<div class="card section-card" id="evi-block"><h3>📷 Evidências de campo <span class="muted" style="font-weight:400">(fotos do local, medições, protocolo do órgão — toque para ampliar)</span></h3><div id="evi-grid" style="display:flex;flex-wrap:wrap;gap:10px">${list.map((e,i)=>`<div style="position:relative;width:120px"><button type="button" class="btn small" data-evi-del="${i}" title="Remover" style="position:absolute;top:2px;right:2px;z-index:2">✕</button>${/^image\//.test(e.type)?`<img src="${e.dataUrl}" alt="${esc(e.name)}" data-evi-view="${i}" style="width:120px;height:120px;object-fit:cover;border-radius:8px;cursor:zoom-in;border:1px solid #d5dee9">`:`<a href="${e.dataUrl}" download="${esc(e.name)}" class="btn small">⬇ ${esc(e.name).slice(0,14)}</a>`}<div class="muted" style="font-size:11px">${esc((e.at||'').slice(0,10))}</div></div>`).join('')}</div><div style="margin-top:10px"><button type="button" class="btn small primary" id="evi-pick">📷 Anexar foto / arquivo</button><input type="file" id="evi-file" accept="image/*,application/pdf" multiple hidden><input class="input" id="evi-caption" placeholder="Legenda opcional p/ próxima foto (ex.: teste de vazão — 12/10)" style="display:inline-block;width:60%;margin-left:8px"></div></div>`;}
function bindEviBlock(doc){const blk=document.getElementById('evi-block');if(!blk)return;const arr=eviFor(doc).slice();const redraw=()=>{document.getElementById('evi-grid').innerHTML=arr.map((e,i)=>`<div style="position:relative;width:120px"><button type="button" class="btn small" data-evi-del="${i}" title="Remover" style="position:absolute;top:2px;right:2px;z-index:2">✕</button>${/^image\//.test(e.type)?`<img src="${e.dataUrl}" alt="${esc(e.name)}" data-evi-view="${i}" style="width:120px;height:120px;object-fit:cover;border-radius:8px;cursor:zoom-in;border:1px solid #d5dee9">`:`<a href="${e.dataUrl}" download="${esc(e.name)}" class="btn small">⬇ ${esc(e.name).slice(0,14)}</a>`}<div class="muted" style="font-size:11px">${esc((e.at||'').slice(0,10))}</div></div>`).join('');wire();};const wire=()=>{blk.querySelectorAll('[data-evi-del]').forEach(b=>b.onclick=()=>{arr.splice(Number(b.dataset.eviDel),1);redraw();});blk.querySelectorAll('[data-evi-view]').forEach(b=>b.onclick=()=>{const e=arr[Number(b.dataset.eviView)];modalBox(e.name||'Evidência',`<img src="${e.dataUrl}" style="max-width:100%;border-radius:8px"><div class="muted">${esc(e.at||'')}</div>`,null,'Fechar');});};wire();document.getElementById('evi-pick')&&(document.getElementById('evi-pick').onclick=()=>{const fi=document.getElementById('evi-file');if(fi)fi.click();});document.getElementById('evi-file').onchange=async ev=>{const cap=(document.getElementById('evi-caption').value||'').trim();for(const file of ev.target.files){try{const item=await eviShrink(file);if(cap)item.caption=cap;arr.push(item);}catch(err){toast('Falha ao anexar '+file.name);}}document.getElementById('evi-caption').value='';ev.target.value='';redraw();toast(arr.length+' evidência(s) — salve o documento para gravar.');};
// colar print de tela (Ctrl+V) direto no bloco de evidências — funciona no modal e na tela do documento
blk.contentEditable='true';blk.style.outline='none';
blk.onpaste=async e=>{e.preventDefault();const items=[...(e.clipboardData&&e.clipboardData.items||[])];let n=0;for(const it of items){if(it.type&&/^image\//.test(it.type)){try{const f=it.getAsFile();if(!f)continue;const item=await eviShrink(f);item.name=item.name||'print-screen.png';const cp=document.getElementById('evi-caption');if(cp&&cp.value.trim())item.caption=cp.value.trim();arr.push(item);n++;}catch(err){}}}if(n){const cp=document.getElementById('evi-caption');if(cp)cp.value='';redraw();toast(n+' imagem(ns) colada(s).');}};
blk._get=()=>arr;}
function readEvidences(){const blk=document.getElementById('evi-block');return blk&&blk._get?blk._get():undefined;}

function eviPrintHtml(o){const list=Array.isArray(o&&o.evidences)?o.evidences.filter(e=>/^image\//.test(e.type||'')):[];if(!list.length)return '';return `<h3>EVIDÊNCIAS DE CAMPO (${list.length})</h3><div class="li" style="display:flex;flex-wrap:wrap;gap:6px">${list.slice(0,12).map(e=>`<img src="${e.dataUrl}" alt="${esc(e.name||'')}" style="width:96px;height:96px;object-fit:cover;border:1px solid #cbd5e1;border-radius:6px">`).join('')}</div>`;}
// lê evidências/custos editados na prévia do documento
function readDocEvi(){const el=document.getElementById('evi-block');return el&&el._get?el._get():undefined;}
function readDocCosts(){const tbl=document.getElementById('cost-table');if(!tbl)return undefined;return [...tbl.querySelectorAll('tbody tr')].map(r=>({desc:(r.querySelector('.cost-desc')||{}).value?.trim()||'',who:(r.querySelector('.cost-who')||{}).value?.trim()||'',value:Number((r.querySelector('.cost-value')||{}).value||0)})).filter(c=>c.desc||c.value);}

// ── Templates completos de Proposta Comercial e Contrato (todos os blocos editáveis no documento) ──
// Texto-canônico de validade: evita duplicações ("Esta proposta possui validade de Esta proposta…") ao renderizar cabeçalho e seção 14 a partir do mesmo valor.
function validityText(o){let v=cleanValidity(String((o&&o.validity)||''));for(let i=0;i<6&&/^Esta proposta possui validade de\s+Esta proposta\b/i.test(v);i++)v=v.replace(/^Esta proposta possui validade de\s*/i,'');if(!v)v='15 dias corridos';const low=v.toLowerCase();if(/^(esta proposta|proposta)\b/.test(low))return v.endsWith('.')?v:v+'.';if(/a contar da data de emiss/.test(low))return 'Esta proposta possui validade de '+v.replace(/\.+$/,'')+'.';if(/^validade\b/.test(low))return 'Esta proposta possui '+v.replace(/\.+$/,'')+'.';return 'Esta proposta possui validade de '+v.replace(/\.+$/,'')+' a contar da data de emissão.';}
// Remove duplicações históricas do texto de validade (ex.: "Esta proposta possui validade de Esta proposta… a contar da data de emissão. a contar da data de emissão.") acumuladas em documentos antigos.
function cleanValidity(s){let v=String(s||'').replace(/\s+/g,' ').trim();if(!v)return '';let prev;do{prev=v;v=v.replace(/Esta proposta possui validade de\s+(?=Esta proposta)/gi,'');v=v.replace(/^(?:Validade:?\s*)?(?:Esta proposta possui(?: validade de)?)?\s*(?:Esta proposta possui(?: validade de)?)?\s*(15\s+dias(?:\s+corridos|\s+[úu]teis)?(?:\s+a contar da data de emiss[ãa]o)?)\s*a contar da data de emiss[ãa]o\.?(\s*a contar da data de emiss[ãa]o\.?)+/i,'$1');}while(v!==prev);return v.trim();}
function fichaHtml(f){return `<table class="tbl svc-ficha"><tr><td>Serviço</td><td><strong>${esc(f.name)}</strong></td></tr><tr><td>Códigos profissionais</td><td>${(f.codes||[]).map(c=>'<code>'+esc(c)+'</code>').join(' ')||'____________'}</td></tr><tr><td>Categoria</td><td>${esc(f.category)||'____________'}</td></tr><tr><td>Responsável técnico</td><td>${f.managed?'Parceiro / Terceirizado habilitado (gerência e coordenação: Agrageo Consultoria)':esc(f.responsible)||'Agrageo (RT próprio)'}${(!f.responsible||/^agrageo/i.test(String(f.responsible)))?rtLineHtml():''}</td></tr>${f.price?`<tr><td>Valor de referência</td><td>${money(Number(f.price))} <span style="color:#718096">(preço padrão do serviço — o valor final é o da seção de investimento)</span></td></tr>`:''}${f.art?`<tr><td>ART/RRT</td><td>${f.art==='sim'?'Aplicável — será emitida pelo responsável técnico':'Não aplicável a este serviço'}</td></tr>`:''}<tr><td>Descrição / escopo</td><td>${esc(f.desc)||'Conforme detalhamento do documento.'}</td></tr></table>`;}
function propTpl(o){return `<div class="paper-header"><img src="./assets/logo-agrageo_1.png" onerror="this.style.display='none'"><div><h2>AGRAGEO CONSULTORIA</h2><p>CNPJ ${esc(o.cnpj)} • ${esc(o.city)} • ${esc(o.phone)} • ${esc(o.email)}</p></div></div><h1 style="text-align:center;font-family:Georgia,serif;color:#b6811d;font-size:17px;letter-spacing:.06em;margin:28px 0 4px">PROPOSTA COMERCIAL</h1><p style="text-align:center;margin:0"><span class="muted">${esc(o.number)} • Emitida em ${esc(o.date)} • Validade: ${validityText(o)}</span></p><h3>CLIENTE</h3><p contenteditable="true"><strong>${esc(o.clientName)}</strong>${o.clientDoc?' — '+esc(o.clientDoc):''}${o.clientAddr?'<br>'+esc(o.clientAddr):''}</p>${execLineHtml(o)}<h3>1. APRESENTAÇÃO DA AGRAGEO</h3><div class="editor" contenteditable="true">A Agrageo Consultoria atua em regularização ambiental e recursos hídricos, georreferenciamento e geoprocessamento, topografia e consultoria técnica, oferecendo levantamentos de campo, processamento de dados, peças técnicas e acompanhamento junto aos órgãos competentes.</div><h3>2. OBJETO DA PROPOSTA</h3><div class="editor" contenteditable="true">${esc(o.scope)||'Prestação de serviços técnicos de levantamento e georreferenciamento, incluindo levantamento de campo, processamento dos dados, elaboração da planta e demais produtos técnicos previstos nesta proposta.'}</div><h3>3. CARACTERIZAÇÃO DO IMÓVEL</h3><table class="tbl" contenteditable="true"><tr><td>Proprietário</td><td>${esc(o.clientName)}</td></tr><tr><td>Endereço / localização</td><td>${esc(o.clientAddr)||'____________'}</td></tr><tr><td>Lote / Quadra</td><td>____________</td></tr><tr><td>Matrícula</td><td>____________</td></tr><tr><td>Área aproximada</td><td>____________</td></tr><tr><td>Município / UF</td><td>${esc(o.clientCity||'')}</td></tr><tr><td>Inscrição imobiliária</td><td>____________</td></tr><tr><td>Coordenadas / referência</td><td>____________</td></tr></table>${o.fichas&&o.fichas.length?('<h3>4. ESCOPO DOS SERVIÇOS</h3>'+o.fichas.map(f=>`<div class="svc-block" contenteditable="true"><h4>${esc(f.name)}</h4>${fichaHtml(f)}</div>`).join('')):'<h3>4. ESCOPO DOS SERVIÇOS</h3><ul class="li" contenteditable="true"><li>Análise da documentação fornecida;</li><li>Planejamento do levantamento;</li><li>Levantamento topográfico/geodésico;</li><li>Coleta de pontos de interesse e determinação das coordenadas;</li><li>Processamento dos dados e cálculo de área e perímetro;</li><li>Elaboração da planta georreferenciada;</li><li>Elaboração do memorial descritivo e quadro de coordenadas;</li><li>Relatório técnico;</li><li>ART/RRT, quando aplicável;</li><li>Entrega dos arquivos digitais.</li></ul>'}${etHtml(o)}<h3 class="sec-metodologia">${5+(o.etapas&&o.etapas.length?1:0)}. METODOLOGIA</h3><div class="editor" contenteditable="true">Equipamento GNSS/RTK (estação total quando necessária); sistema de referência SIRGAS 2000; processamento e ajustamento dos dados; precisão compatível com as normas aplicáveis; critérios técnicos conforme NBR 13.133 e exigências do órgão competente.</div><h3>${6+(o.etapas&&o.etapas.length?1:0)}. PRODUTOS / ENTREGÁVEIS</h3><table class="tbl" contenteditable="true"><tr><th>Produto</th><th>Formato</th></tr><tr><td>Planta georreferenciada</td><td>PDF/DWG</td></tr><tr><td>Memorial descritivo</td><td>PDF</td></tr><tr><td>Quadro de coordenadas</td><td>PDF/XLSX</td></tr><tr><td>Arquivo vetorial</td><td>DWG/DXF/SHP</td></tr><tr><td>Relatório técnico</td><td>PDF</td></tr></table><h3>${7+(o.etapas&&o.etapas.length?1:0)}. PRAZO</h3><div class="editor" contenteditable="true">${esc(o.deadline)||'Prazo estimado de até 15 (quinze) dias úteis, contados a partir da aprovação desta proposta e do pagamento do sinal, condicionado também à disponibilização da documentação necessária e à liberação de acesso ao imóvel. Prazos de análise dos órgãos públicos não são de responsabilidade da Agrageo.'}</div><h3>${8+(o.etapas&&o.etapas.length?1:0)}. INVESTIMENTO</h3><p style="font-size:16px;margin:6px 0"><strong>${money(o.value)}</strong></p><div class="editor" contenteditable="true">Forma de pagamento: ${(()=>{const pay=String(o.payment||'').replace(/^(forma de pagamento:?\s*)/i,'').trim();if(!pay||/^r\$\s*[\d.,]+\s*$/i.test(pay))return 'sinal de 50% na confirmação da contratação e o saldo de 50% na entrega dos produtos finais, via PIX ou transferência bancária.';return esc(pay);})()}</div>${acHtml(o)}<h3>${secN(10,o)}. O QUE ESTÁ INCLUÍDO</h3><ul class="li" contenteditable="true"><li>Todos os serviços e produtos listados nos itens 4, 5 e 6;</li><li>Honorários técnicos da Agrageo Consultoria.</li></ul><h3>${secN(11,o)}. O QUE NÃO ESTÁ INCLUÍDO</h3><ul class="li" contenteditable="true"><li>Taxas municipais e emolumentos cartorários;</li><li>Custos de terceiros;</li><li>Retificações decorrentes de documentação incorreta fornecida pelo cliente;</li><li>Novos levantamentos causados por alteração do escopo;</li><li>Serviços não previstos nesta proposta.</li></ul><h3>${secN(12,o)}. RESPONSABILIDADES DO CLIENTE</h3><ul class="li" contenteditable="true"><li>Fornecer matrícula e documentação do imóvel;</li><li>Permitir acesso ao imóvel;</li><li>Informar limites conhecidos e confrontantes;</li><li>Disponibilizar documentos necessários à execução.</li></ul><h3>${secN(13,o)}. VALIDADE DA PROPOSTA</h3><div class="editor" contenteditable="true">${validityText(o)}</div><h3>${secN(14,o)}. ACEITE DA PROPOSTA COMERCIAL</h3><p>Ao assinar este instrumento, o CONTRATANTE declara estar de acordo com o escopo, prazo, valores e condições desta Proposta Comercial${o.number?', '+esc(o.number):''}.</p>${localDataLine(o.city)}${signatureBlock('CONTRATANTE','','Nome: ____________  CPF/CNPJ: ____________','CONTRATADA','AGRAGEO CONSULTORIA','CNPJ: '+o.cnpj)}`;}
function contTpl(o){const C=(n,t)=>`<h3>CLÁUSULA ${n}</h3><div class="editor" contenteditable="true">${t}</div>`;return `<div class="paper-header"><img src="./assets/logo-agrageo_1.png" onerror="this.style.display='none'"><div><h2>AGRAGEO CONSULTORIA</h2><p>CNPJ ${esc(o.cnpj)} • ${esc(o.city)} • ${esc(o.phone)} • ${esc(o.email)}</p></div></div><h1 style="text-align:center;font-family:Georgia,serif;color:#b6811d;font-size:16px;letter-spacing:.05em;margin:28px 0 4px">CONTRATO DE PRESTAÇÃO DE SERVIÇOS TÉCNICOS</h1><p style="text-align:center;margin:0"><span class="muted">${esc(o.number)}</span></p>${C('1 – DAS PARTES','<strong>CONTRATADA:</strong> '+esc(o.company)+', CNPJ nº '+esc(o.cnpj)+', com sede em '+esc(o.city)+', representada por seu representante legal.<br><strong>CONTRATANTE:</strong> '+esc(o.clientName)+(o.clientDoc?', '+esc(o.clientDoc):'')+(o.clientAddr?', '+esc(o.clientAddr):'')+'.')}<p contenteditable="true">As partes acima qualificadas celebram o presente contrato, que se regerá pelas cláusulas seguintes e pela Proposta Comercial${o.origin?', '+esc(o.origin):''} que passa a fazer parte integrante deste instrumento.</p>${C('2 – DO OBJETO','O presente contrato tem por objeto a prestação de serviços técnicos de levantamento e georreferenciamento urbano'+(o.service?' do serviço “'+esc(o.service)+'”':'')+', conforme condições, escopo e produtos descritos neste instrumento e na Proposta Comercial de origem.')}${C('3 – DO ESCOPO','Fazem parte do escopo contratado: '+esc(o.scope)+' Somente integram a obrigação da CONTRATADA os serviços expressamente previstos neste contrato.')}<p contenteditable="true">Parágrafo único. Qualquer atividade não prevista no escopo será considerada serviço adicional, sujeita a orçamento prévio e aprovação do CONTRATANTE (Cláusula 10).</p>${o.fichas&&o.fichas.length?'<h3>DO OBJETO — FICHAS TÉCNICAS DOS SERVIÇOS CONTRATADOS</h3>'+o.fichas.map(f=>`<div class="svc-block" contenteditable="true"><h4>${esc(f.name)}</h4>${fichaHtml(f)}</div>`).join(''):''}${C('4 – DOS PRODUTOS E ENTREGÁVEIS','A CONTRATADA entregará ao CONTRATANTE: planta georreferenciada (PDF/DWG), memorial descritivo (PDF), quadro de coordenadas (PDF/XLSX), arquivo vetorial (DWG/DXF/SHP) e relatório técnico (PDF), nos formatos e quantidades acordados.')}${C('5 – DA METODOLOGIA E DOS CRITÉRIOS TÉCNICOS','Levantamento GNSS/RTK (e estação total, quando necessário); sistema de referência SIRGAS 2000; processamento e ajustamento dos dados; precisão compatível com as normas técnicas aplicáveis (NBR 13.133 e exigências dos órgãos competentes).')}${C('6 – DO PRAZO','O prazo de execução será de '+(o.deadline?esc(o.deadline):'até 10 dias úteis')+', contado a partir da ocorrência cumulativa de: (i) assinatura do contrato; (ii) pagamento da parcela inicial; (iii) disponibilização da documentação necessária; e (iv) liberação de acesso ao imóvel. Prazos de análise de órgãos públicos não compõem o prazo da CONTRATADA.')}${C('7 – DO VALOR E PAGAMENTO','O CONTRATANTE pagará à CONTRATADA o valor total de '+money(o.value)+', da seguinte forma: '+esc(o.payment)+'. Em caso de atraso, incidirão multa de 2% e juros de mora de 1% ao mês. O não pagamento da parcela inicial condiciona o início da execução.')}${acHtml(o)}${C(secN(8,o)+' – DAS OBRIGAÇÕES DA CONTRATADA','Executar os serviços conforme escopo; utilizar metodologia adequada e profissionais habilitados; entregar os produtos contratados; manter sigilo sobre informações do cliente; comunicar formalmente impedimentos técnicos.')}${C(secN(9,o)+' – DAS OBRIGAÇÕES DO CONTRATANTE','Fornecer documentos verdadeiros e completos; garantir acesso ao imóvel; indicar responsável para contato; efetuar os pagamentos nas condições ajustadas; informar restrições de acesso e características conhecidas do imóvel.')}${C(secN(10,o)+' – DAS ALTERAÇÕES DE ESCOPO','Qualquer atividade não prevista no escopo contratado será considerada serviço adicional e dependerá de prévia aprovação do CONTRATANTE, podendo resultar em alteração de prazo e de preço.')}${C(secN(11,o)+' – DOS SERVIÇOS ADICIONAIS','Serviços adicionais serão orçados previamente por escrito (e-mail ou termo aditivo), somente sendo executados após a aprovação do CONTRATANTE.')}${C(secN(12,o)+' – DA RESPONSABILIDADE TÉCNICA','Os serviços serão executados sob responsabilidade técnica do Técnico em Geoprocessamento ALEX DA SILVA AGRA, Registro Nacional nº 01039973183 (Processo 5292596/2024, SIN-CRT), com emissão de ART/RRT quando aplicável ao serviço efetivamente executado; atividades de outras profissões regulamentadas serão conduzidas por parceiros devidamente habilitados, sob coordenação da CONTRATADA.')}${C(secN(13,o)+' – DAS LIMITAÇÕES E CONDIÇÕES TÉCNICAS','A precisão dos trabalhos depende das condições de campo, do acesso ao imóvel, da disponibilidade de sinais GNSS, de obstáculos e condições ambientais, das informações fornecidas pelo cliente e da inexistência de conflitos de divisas. Impedimentos alheios à vontade da CONTRATADA suspendem os prazos.')}${C(secN(14,o)+' – DA DOCUMENTAÇÃO FORNECIDA PELO CLIENTE','A CONTRATADA trabalha exclusivamente com os documentos apresentados pelo CONTRATANTE; inconsistências documentais podem exigir diligências ou serviços adicionais, sem custo para a CONTRATADA.')}${C(secN(15,o)+' – DA ENTREGA E ACEITE','Os produtos serão entregues em meio digital. Considera-se concluída a entrega com o envio dos arquivos; o CONTRATANTE dispõe de 10 (dez) dias para apontar desconformidades, findos os quais os serviços serão considerados aceitos.')}${C(secN(16,o)+' – DA REVISÃO E CORREÇÃO','Erros técnicos de responsabilidade da CONTRATADA serão corrigidos sem custo. Alterações, complementações ou novos levantamentos solicitados pelo CONTRATANTE caracterizam serviço adicional (Cláusula 10).')}${C(secN(17,o)+' – DO CANCELAMENTO E RESCISÃO','Em caso de desistência pelo CONTRATANTE, serão devidos os valores proporcionais aos serviços já executados e as despesas comprovadamente arcadas. A rescisão por inadimplência ou impossibilidade técnica/accesso será comunicada por escrito, apurando-se as responsabilidades.')}${C(secN(18,o)+' – DA CONFIDENCIALIDADE E PROTEÇÃO DE DADOS','As partes obrigam-se a manter sigilo sobre documentos e dados pessoais tratados em razão deste contrato, observada a LGPD (Lei nº 13.709/2018).')}${C(secN(19,o)+' – DA PROPRIEDADE DOS PRODUTOS','Após a quitação integral, os produtos finais poderão ser utilizados pelo CONTRATANTE para a finalidade contratada. Arquivos editáveis (DWG/DXF/SHP) serão fornecidos somente se previstos no escopo.')}${C(secN(20,o)+' – DO FORO','Fica eleito o foro da comarca de '+esc(o.city)+', com renúncia a qualquer outro, por mais privilegiado que seja.')}${localDataLine(o.city)}<h3>ASSINATURAS</h3>${signatureBlock(o.clientName||'CONTRATANTE','CONTRATANTE','CPF/CNPJ: ____________',o.company,'CONTRATADA','CNPJ: '+o.cnpj)}${signatureBlock('ALEX DA SILVA AGRA','Responsável Técnico','Técnico em Geoprocessamento · Registro Nacional: 01039973183','TESTEMUNHA','Testemunha','CPF: ____________')}`;}
function docHtml(type,o){return type==='proposal'?propTpl(o):type==='work_order'?osTpl(o):type==='delivery_term'?termTpl(o):contTpl(o);}
